const api = ApiClients();
const apiReportes = ApiReportes();
const apiCatalogs = CatalogApi();

function ConsultaAfiliadosTable({
    data,
    watch,
    catalogState,
    dataStatus
}: {
    data: any | null;
    watch: any;
    catalogState: CatalogState;
    dataStatus: any
}) {
    const forcesId: number[] = Array.from(new Set(data?.map((x: any) => x.idFuerza)))

    return (
        <div>
            {data.length > 0 ? (
                <table className="client-table">
                    <thead>
                        <tr>
                            <th>Fuerza</th>
                            <th>Estado</th>
                            <th>Conteo</th>
                        </tr>
                    </thead>
                    <tbody>
                        {catalogState.Force.filter(obj => forcesId.includes(obj.id)).map((force: FORCEDTO, index) => {
                            const statusCount = dataStatus?.length ?? 0;
                            return dataStatus?.map((status: any, statusIndex: any) => {
                                if (statusIndex === 0) {
                                    return (
                                        <tr key={`table-${index}`}>
                                            <td data-label="Número Cuenta" className="tab-space-01" rowSpan={statusCount}>{force.descripcion}</td>
                                            <td data-label="Número Cuenta" className="tab-space-01">{status.descriptions}</td>
                                            <td data-label="Número Cuenta" className="tab-space-01">{data?.find(x => x.idFuerza === force.id && x.idEstado === status.secondsId)?.conteo ?? 0}</td>
                                        </tr>
                                    );
                                }
                                return (
                                    <tr key={`table-${index}`}>
                                        <td data-label="Número Cuenta" className="tab-space-01">{status.descriptions}</td>
                                        <td data-label="Número Cuenta" className="tab-space-01">{data?.find(x => x.idFuerza === force.id && x.idEstado === status.secondsId)?.conteo ?? 0}</td>
                                    </tr>
                                );
                            });
                        })}
                    </tbody>
                </table>
            ) : null}
        </div>

    );
}

const ConsultaAfiliadosPorFuerza = ({
    catalogState,
    startGetAllGrades,
    startGetAllForces,
    startGetCategory,
    startGetAllExecutingUnits,
    startGetAllIdentificationTypes
}: {
    catalogState: CatalogState;
    startGetAllGrades: () => void;
    startGetAllForces: () => void;
    startGetCategory: () => void;
    startGetAllExecutingUnits: () => void;
    startGetAllIdentificationTypes: () => void;
}) => {
    const classes = useStyles();

    useEffect(() => {
        startGetAllGrades()
        startGetAllForces()
        startGetCategory()
        startGetAllExecutingUnits()
        startGetAllIdentificationTypes()
        getClientState();
    }, [])

    const [data, setData] = useState([]);
    const [dataClientState, setDataClientState] = useState([]);
    const [loading, setLoading] = useState(false);

    const { control, handleSubmit, watch } = useForm<any>({
        defaultValues: {
            fuerza: 0,
        }
    });

    const getClientState = () => {
        apiCatalogs.getEstadosCliente()
            .then((response) => {
                setDataClientState(response.data)
            })
    }

    const [publicIpAddress, setPublicIpAddress] = useState<string | null>(null);
    const [localIpAddress, setLocalIpAddress] = useState<string | null>(null);
    const catalogApi = CatalogApi();

    const isValidIPv4 = (ip: string) => {
        const ipv4Regex = /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
        return ipv4Regex.test(ip);
    };

    const isValidIPv6 = (ip: string) => {
        const ipv6Regex = /([a-f0-9:]+:+)+[a-f0-9]+/i;
        return ipv6Regex.test(ip);
    };

    const enviarIp = async (ip: any) => {
        const convertIp = ip.split('.')[0]

        const hexadecimal = convertIp
        await catalogApi
            .getObtenerIpLocal(hexadecimal)
            .then(async (response: any) => {

                if (response) {
                    if (response.isSuccess) {
                        setPublicIpAddress(response.data);
                    }
                }
            })
            .catch(e => {
                toast('Error del sistema', { type: toast.TYPE.ERROR });
            });

    }

    useEffect(() => {
        const fetchLocalIPAddress = () => {
            const peerConnection = new RTCPeerConnection({ iceServers: [] });
            peerConnection.createDataChannel('');
            peerConnection.createOffer()
                .then((offer) => peerConnection.setLocalDescription(offer))
                .catch((error) => console.error('Error creating offer:', error));

            peerConnection.onicecandidate = (event) => {
                if (event.candidate) {
                    const ip: any = event.candidate.address;
                    if (isValidIPv4(ip) || isValidIPv6(ip)) {
                        setLocalIpAddress(ip);
                        enviarIp(ip);
                    } else {
                        setLocalIpAddress(ip);
                        enviarIp(ip);
                    }
                }
            };

            return () => {
                peerConnection.close();
            };
        };
        fetchLocalIPAddress();

    }, []);

    // const handleSearchButton = async (datos: any) => {

    //     setLoading(true)
    //     api.getConsultaAfiliadosPorFuerza(datos.fuerza)
    //         .then((response) => {
    //             if (response.isSuccess) {
    //                 setData(response.data)
    //                 const auditoriaApi = AuditoriaApi();
    //                 const user = AuthService.getUserInfo();
    //                 const nav = window.navigator as any;
    //                 const usrAg = nav.userAgentData.brands.find(
    //                     (x: { brand: string }) => x.brand === 'Google Chrome' || x.brand === 'Microsoft Edge'
    //                 )?.brand;

    //                 const requestAuditoria = {
    //                     navegador: usrAg,
    //                     sistemaOperativo: nav.userAgentData.platform,
    //                     nombreUsuario: user.USR_USERNAME,
    //                     usurioId: user.USR_ID,
    //                     ip: publicIpAddress,
    //                     modulo: 'Generación de Reportes GA2',
    //                     hostname: document.location.host,
    //                     tipoAccion: 'CONSULTAS',
    //                     idTipoAccion: 3,
    //                     // descripcion: `Consulta de afiliados con los siguientes filtros:
    //                     //                 - Periodo Inicial: ${fechaInicialIndice || 'No especificada'}
    //                     //                 - Periodo Final: ${fechaFinalIndice || 'No especificada'}`,
    //                 } as Auditoria;

    //                 auditoriaApi.InsertAuditoria(requestAuditoria);
    //             } else {
    //                 toast('Error en la consulta')
    //             }
    //         })
    //         .catch(() => {
    //             toast('Error en la consulta')
    //         })
    //         .finally(() => {
    //             setLoading(false)
    //         })
    // };

    const handleSearchButton = async (datos: any) => {
        setLoading(true);

        // Buscar descripción de la fuerza seleccionada
        const fuerzaSeleccionada = catalogState.Force.find(
            (f: any) => f.id === datos.fuerza
        );
        const forceDesc = fuerzaSeleccionada?.descripcion || 'No especificada';

        const auditoriaApi = AuditoriaApi();
        const user = AuthService.getUserInfo();
        const nav = window.navigator as any;
        const usrAg = nav.userAgentData?.brands?.find(
            (x: { brand: string }) => x.brand === 'Google Chrome' || x.brand === 'Microsoft Edge'
        )?.brand;

        api.getConsultaAfiliadosPorFuerza(datos.fuerza)
            .then((response) => {
                if (response.isSuccess) {
                    setData(response.data);

                    // Auditoría de consulta exitosa
                    const requestAuditoria: Auditoria = {
                        navegador: usrAg,
                        sistemaOperativo: nav.userAgentData.platform,
                        nombreUsuario: user.USR_USERNAME,
                        usurioId: user.USR_ID,
                        ip: publicIpAddress,
                        modulo: 'Generación de Reportes GA2',
                        hostname: document.location.host,
                        tipoAccion: 'CONSULTAS',
                        idTipoAccion: 3,
                        descripcion: `Consulta de afiliados con los siguientes filtros:
                                      - Fuerza: ${forceDesc}`
                    };

                    auditoriaApi.InsertAuditoria(requestAuditoria);
                } else {
                    toast('Error en la consulta');

                    // Auditoría de error funcional
                    const requestAuditoriaError: Auditoria = {
                        navegador: usrAg,
                        sistemaOperativo: nav.userAgentData?.platform,
                        nombreUsuario: user?.USR_USERNAME,
                        usurioId: user?.USR_ID,
                        ip: publicIpAddress,
                        modulo: 'Generación de Reportes GA2',
                        hostname: document.location.host,
                        tipoAccion: 'ERRORES Y EXCEPCIONES',
                        idTipoAccion: 8,
                        descripcion: `Error en la consulta de afiliados.
                                      - Fuerza: ${forceDesc}
                                      - Mensaje API: ${response?.returnMessage || 'No disponible'}`
                    };

                    auditoriaApi.InsertAuditoria(requestAuditoriaError);
                }
            })
            .catch((error) => {
                toast('Error en la consulta');

                // Auditoría de excepción
                const requestAuditoriaError: Auditoria = {
                    navegador: usrAg,
                    sistemaOperativo: nav.userAgentData?.platform,
                    nombreUsuario: user?.USR_USERNAME,
                    usurioId: user?.USR_ID,
                    ip: publicIpAddress,
                    modulo: 'Generación de Reportes GA2',
                    hostname: document.location.host,
                    tipoAccion: 'ERRORES Y EXCEPCIONES',
                    idTipoAccion: 8,
                    descripcion: `Excepción al consultar afiliados por fuerza.
                                  - Fuerza: ${forceDesc}
                                  - Error: ${error?.message || 'Error desconocido'}
                                  - Código HTTP: ${error?.response?.status || 'No disponible'}`
                };

                auditoriaApi.InsertAuditoria(requestAuditoriaError);
            })
            .finally(() => {
                setLoading(false);
            });
    };


    const GenerarExcel = async () => {
        const columnDataList = data?.map((row: any) => ({
            data: [
                String(catalogState?.IdentificationType.find(x => x.id === row.idTipoIdentificacion)?.descripcion) || '',
                String(row.identificacion) || '',
                String(`${row.primerNombre} ${row.primerApellido}`) || '',
                String(catalogState.Force.find(x => x.id === row.idFuerza)?.descripcion) || '',
                String(catalogState.ExecutingUnit.find(x => x.id === row.idUnidadEjecutora)?.nombre) || '',
                String(catalogState.Grade.find(x => x.id === row.idGrado)?.descripcion) || ''
            ]

        }));

        const request = {
            columnDataList: columnDataList.map(item => ({
                data: item.data
            })),
            columnName: [
                "Tipo Identificación", "Número identificación",
                "Nombre", "Fuerza", "Unidad Ejecutora", "Grado"
            ]
        };
        const response = await apiReportes.GenerarExcels(request);
        const blob = new Blob([response], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `Consulta-Afiliados:${moment().format()}.csv`;
        document.body.appendChild(link);
        link.click();
        window.URL.revokeObjectURL(url);


        const auditoriaApi = AuditoriaApi();
        const user = AuthService.getUserInfo();
        const nav = window.navigator as any;
        const usrAg = nav.userAgentData.brands.find(
            (x: { brand: string }) => x.brand === 'Google Chrome' || x.brand === 'Microsoft Edge'
        )?.brand;

        const requestAuditoria = {
            navegador: usrAg,
            sistemaOperativo: nav.userAgentData.platform,
            nombreUsuario: user.USR_USERNAME,
            usurioId: user.USR_ID,
            ip: publicIpAddress,
            modulo: 'Generación de Reportes GA2',
            hostname: document.location.host,
            tipoAccion: 'DESCARGAS',
            idTipoAccion: 5,
            descripcion: 'Descarga de archivo Excel reporte GA2'

        } as Auditoria;

        auditoriaApi.InsertAuditoria(requestAuditoria);
    }

    return (
        <div>
            <CHPaper title="Consulta afiliados">
                <LoadingComponent key="loader" loading={loading} />
                <Grid container>
                    <Grid className={classes.column} item xs={12} md={3}>
                        <Controller
                            control={control}
                            rules={{
                                required: 'Este campo es requerido',
                            }}
                            render={({
                                field: { onChange, value }
                            }) => (
                                <CHSelect
                                    defaultValue=""
                                    label="Fuerza"
                                    value={value}
                                    onChange={onChange}
                                // onChange={(event) => {

                                //     onChange(event.target.value);
                                // }}
                                >
                                    <MenuItem key={0} value={0}>SELECCIONE FUERZA</MenuItem>
                                    {catalogState.Force.map((option: any) => (
                                        <MenuItem key={option.id} value={option.id}>
                                            {option.descripcion}
                                        </MenuItem>
                                    ))}
                                </CHSelect>
                            )}
                            name="fuerza"
                        />
                    </Grid>
                    <Grid className={classes.column} item xs={12} md={4}>
                        <Button
                            variant="contained"
                            color="primary"
                            className={classes.button}
                            onClick={handleSubmit(handleSearchButton)}
                        >
                            CONSULTAR
                        </Button>
                    </Grid>
                    {/* <Grid className={classes.column} item xs={12} md={4}>
                        <Button
                            variant="contained"
                            color="primary"
                            className={classes.button}
                            onClick={GenerarExcel}
                        >
                            GENERAR EXCEL
                        </Button>
                    </Grid> */}
                </Grid>
            </CHPaper>
            <ConsultaAfiliadosTable
                data={data}
                watch={watch}
                catalogState={catalogState}
                dataStatus={dataClientState}
            />
        </div>
    );
};

const mapStateToProps = (state: AppState) => ({
    clientState: state.client,
    catalogState: state.catalog,
    loginState: state.login,
});

const mapDispatchToProps = {
    startGetAllGrades,
    startGetAllForces,
    startGetCategory,
    startGetAllExecutingUnits,
    startGetAllIdentificationTypes
};

export default connect(mapStateToProps, mapDispatchToProps)(ConsultaAfiliadosPorFuerza);
