import React, { useEffect } from 'react';
import { Button, createStyles, makeStyles } from '@material-ui/core';
import { UseFormHandleSubmit } from 'react-hook-form';
import { BOTONERA_SOLICITUD } from '../../../../constants/constants';
import { useIp } from '../../../../shared/context/IpContext';
import AuditoriaApi from '../../../../services/api-auditorias.servise';
import AuthService from '../../../../services/auth.service';

const useStyles = makeStyles(() =>
	createStyles({
		column: {
			padding: '10px',
			textAlign: 'center',
		},
		button: {
			width: '120px',
			marginLeft: '.5rem',
		},
		column2: {
			padding: '10px',
			textAlign: 'left',
		},
		buttonAdd: {
			width: '200px',
			marginLeft: '.5rem',
		},
		columnButtonAdd: {
			textAlign: 'right',
		},
		columnLabel: {
			padding: '10px',
		},
	}),
);

function BotoneraSolicitud({
	onItemGoBack,
	onSubmit,
	onSubmitAprobar,
	onSubmitRechazar,
	onSubmitAnular,
	tipoAccion,
	handleSubmit,
	tipoAccionDetalleProcesar,
	tipoSolicitud,
	cambiarEstadoTramite,
	trazabilidad,
	isloading
}: {
	onItemGoBack: () => void;
	onSubmit: () => void;
	onSubmitAprobar: () => void;
	onSubmitRechazar: () => void;
	onSubmitAnular: () => void;
	tipoAccion: number;
	handleSubmit: UseFormHandleSubmit<any> | undefined;
	tipoAccionDetalleProcesar: boolean;
	tipoSolicitud: any;
	cambiarEstadoTramite: any;
	trazabilidad: any;
	isloading: boolean;
}) {


	const classes = useStyles();
	const { publicIp } = useIp();


	const auditoriaApi = AuditoriaApi();
	const user = AuthService.getUserInfo();

	const registrarAuditoriaGuardarActualizar = (accion: string) => {
		if (!publicIp) {
			console.warn("IP aún no disponible");
			return;
		}

		const nav = window.navigator as any;
		const usrAg = nav.userAgentData?.brands.find(
			(x: { brand: string }) => x.brand === "Google Chrome" || x.brand === "Microsoft Edge"
		)?.brand || "Navegador desconocido";

		const requestAuditoria = {
			navegador: usrAg,
			sistemaOperativo: nav.userAgentData?.platform || "Desconocido",
			nombreUsuario: user.USR_USERNAME,
			usurioId: user.USR_ID,
			ip: publicIp,
			modulo: "Solicitudes",
			hostname: document.location.host,
			tipoAccion: "GUARDAR/ACTUALIZAR",
			idTipoAccion: 4,
			descripcion: `El usuario ${user.USR_USERNAME} realizó la acción: ${accion}`,
		};

		auditoriaApi.InsertAuditoria(requestAuditoria);
	};

	const registrarAuditoriaAprobar = (accion: string) => {
		if (!publicIp) {
			console.warn("IP aún no disponible");
			return;
		}

		const nav = window.navigator as any;
		const usrAg = nav.userAgentData?.brands.find(
			(x: { brand: string }) => x.brand === "Google Chrome" || x.brand === "Microsoft Edge"
		)?.brand || "Navegador desconocido";

		const requestAuditoria = {
			navegador: usrAg,
			sistemaOperativo: nav.userAgentData?.platform || "Desconocido",
			nombreUsuario: user.USR_USERNAME,
			usurioId: user.USR_ID,
			ip: publicIp,
			modulo: "Solicitudes",
			hostname: document.location.host,
			tipoAccion: "APROBAR",
			idTipoAccion: 4,
			descripcion: `El usuario ${user.USR_USERNAME} realizó la acción: ${accion}`,
		};

		auditoriaApi.InsertAuditoria(requestAuditoria);
	};

	const registrarAuditoriaAnular = (accion: string) => {
		if (!publicIp) {
			console.warn("IP aún no disponible");
			return;
		}

		const nav = window.navigator as any;
		const usrAg = nav.userAgentData?.brands.find(
			(x: { brand: string }) => x.brand === "Google Chrome" || x.brand === "Microsoft Edge"
		)?.brand || "Navegador desconocido";

		const requestAuditoria = {
			navegador: usrAg,
			sistemaOperativo: nav.userAgentData?.platform || "Desconocido",
			nombreUsuario: user.USR_USERNAME,
			usurioId: user.USR_ID,
			ip: publicIp,
			modulo: "Solicitudes",
			hostname: document.location.host,
			tipoAccion: "ANULAR",
			idTipoAccion: 4,
			descripcion: `El usuario ${user.USR_USERNAME} realizó la acción: ${accion}`,
		};

		auditoriaApi.InsertAuditoria(requestAuditoria);
	};
	return (
		<>
			<div className="buttons">
				{handleSubmit !== undefined ? (
					<Button
						className={classes.button}
						variant="outlined"
						onClick={() => {
							handleSubmit(onSubmit)();
							registrarAuditoriaGuardarActualizar(tipoAccion === BOTONERA_SOLICITUD.GUARDAR ? "GUARDAR" : "ACTUALIZAR");
						}}
						disabled={tipoAccionDetalleProcesar}
					>
						{tipoAccion === BOTONERA_SOLICITUD.GUARDAR
							? 'GUARDAR'
							: 'ACTUALIZAR'}
					</Button>
				) : (
					<Button
						className={classes.button}
						variant="outlined"
						onClick={() => {
							onSubmit();
							registrarAuditoriaGuardarActualizar(tipoAccion === BOTONERA_SOLICITUD.GUARDAR ? "GUARDAR1" : "ACTUALIZAR");
						}}
						disabled={tipoAccionDetalleProcesar}
					>
						{tipoAccion === BOTONERA_SOLICITUD.GUARDAR
							? 'GUARDAR'
							: 'ACTUALIZAR'}
					</Button>
				)}
				{tipoAccion === BOTONERA_SOLICITUD.ACTUALIZAR ? (
					<Button
						className={classes.button}
						variant="outlined"
						onClick={() => {
							onSubmitAprobar();
							registrarAuditoriaAprobar("APROBAR");
						}}
						disabled={cambiarEstadoTramite === false && (tipoAccionDetalleProcesar || tipoSolicitud === 'EN TRÁMITE' || tipoSolicitud === undefined)}
					>
						APROBAR
					</Button>
				) : (
					''
				)}
				{tipoAccion === BOTONERA_SOLICITUD.ACTUALIZAR ? (
					<Button
						className={classes.button}
						variant="outlined"
						onClick={() => {
							onSubmitAnular();
							registrarAuditoriaAnular("ANULAR");
						}}
						disabled={((trazabilidad && trazabilidad.length >= 1 &&
							trazabilidad[1]?.descripcionEstadoSolicitud === 'RECHAZADA')) || tipoAccionDetalleProcesar
						}
					>
						ANULAR
					</Button>
				) : (
					null
				)}
				<Button
					className={classes.button}
					variant="outlined"
					onClick={() => {
						onItemGoBack();
					}}
				>
					REGRESAR
				</Button>
			</div>
		</>
	);
}

export default BotoneraSolicitud;


