
import React, { useEffect, useState } from 'react';
import { Controller, useForm } from 'react-hook-form';
import {
    Button,
    createStyles,
    Dialog,
    Grid,
    makeStyles,
    MenuItem,
    Typography,
} from '@material-ui/core';
import { toast } from 'react-toastify';
import moment from 'moment';
import CHSelect from '../../../../components/ch-select/CHSelect';
import CHDatePicker from '../../../../components/ch-datepicker/CHDatepicker';
import CHTextField from '../../../../components/ch-text-field/CHTextField';
import CHPaper from '../../../../components/ch-paper/CHPaper';
import ApiproductoClients from '../../../../services/api-producto.service';

const useStyles = makeStyles(() =>
    createStyles({
        titleform: {
            width: '100%',
            textAlign: 'left',
            color: '#1C3F8B',
            padding: 1,
            fontWeight: 'bold',
            fontSize: '1rem',
            marginTop: '1rem'
        },
        column: {
            padding: '10px',
            textAlign: 'center',
        },
        button: {
            width: '100%',
            marginLeft: '.5rem',
            marginTop: '1.5rem',
        },
        columnDate: {
            minWidth: '110px',
        },
        input: {
            boxSizing: 'border-box',
            height: '2em'
        }
    }),
);

type formValues = {
    tipoNovedad: number | null,
    tipoCausal: number | null,
    fechaNovedad: Date | null,
    fechaFinalizacion: Date | null,
    estado: number | null,
    seguroVida: number | null,
    seguroHogar: number | null,
    interesCorriente: any | null,
    interesMora: number | null,
    interesRemanente: number | null,
    capitalRemanente: number | null,
    capital: number | null,
    totalDeuda: number | null,
    valorPagado: number | null,
    cuotaCredito: number | null
};

export const ModalNovedad = (props: any) => {
    const classes = useStyles();
    const cartera = ApiproductoClients();
    const {
        open,
        handleSubmit,
        handleClose,
        producto,
        tipoNovedades,
        tiposCausales,
        estadosNovedades,
        readOnly,
        novedad,
        idCredito,
        estadoCredito,
        idEstadoCredito,
        productoData
    } = props;

    const form = useForm<formValues>({
        defaultValues: {
            fechaNovedad: new Date(),
            fechaFinalizacion: new Date(),
        },
        mode: 'onChange'
    });

    const [mostrarCausal, setMostrarCausal] = useState<boolean>(false);

    useEffect(() => {
        form.reset({
            fechaNovedad: new Date(),
            fechaFinalizacion: new Date(),
        });

        if (novedad) {
            setValues(novedad);
        } else {
            obtenerSaldoObligacion()
                .then((saldo: any) => {
                    setValues(saldo);
                });
        }

    }, [novedad])


    const obtenerSaldoObligacion = () =>
        cartera
            .getSaldoObligacion(producto.idCredito)
            .then(async (response: any) => response?.data)
            .catch(() => toast("Error del sistema", { type: toast.TYPE.ERROR }));

    const setValues = (novedad: any) => {

        const currentDate = new Date();
        const dateNovedad = moment(currentDate).startOf('day');
        const dateFinalizacion = moment(currentDate).startOf('day').endOf('month');

        form.setValue('tipoNovedad', novedad?.idTipoNovedad);
        form.setValue('tipoCausal', novedad?.idTipoCausal);
        form.setValue('fechaNovedad', novedad?.fechaNovedad ?? dateNovedad.toDate());
        form.setValue('fechaFinalizacion', novedad?.fechaFinalizacion ?? dateFinalizacion.toDate());
        form.setValue('estado', novedad?.idEstadoNovedad);
        form.setValue('seguroVida', novedad?.seguroVida);
        form.setValue('seguroHogar', novedad?.seguroHogar);
        form.setValue('interesCorriente', novedad?.interesCorriente);
        form.setValue('interesMora', novedad?.interesMora);
        form.setValue('interesRemanente', novedad?.interesRemanente);
        form.setValue('capitalRemanente', novedad?.capitalRemanente);
        form.setValue('capital', novedad?.capital);
        form.setValue('totalDeuda', novedad?.totalDeuda);
        form.setValue('valorPagado', novedad?.valorPagado);
        form.setValue('cuotaCredito', novedad?.cuotaCredito);

        const tipoNovedad = tipoNovedades.find((x: any) => x?.id === novedad?.idTipoNovedad)?.codigo;
        setMostrarCausal(tipoNovedad === "ACELERACION" ||
            tipoNovedad === "RESTITUCIÓN INMUEBLE" || tipoNovedad === "REDIFERIDO");

    };

    const [capital, setCapital] = useState('');
    const [seguroVida, setSeguroVida] = useState('');
    const [seguroHogar, setSeguroHogar] = useState('');
    const [interesCorriente, setInteresCorriente] = useState('');
    const [interesMora, setInteresMora] = useState('');
    const [capitalRemanente, setCapitalRemanente] = useState('');
    const [interesRemanente, setInteresRemanente] = useState('');
    const [totalDeuda, setTotalDeuda] = useState('');
    const [saldoCapital, setSaldoCapital] = useState(0);

    const obtenerTiposCausalesInmueble = () => {
        if (estadoCredito === "RESTITUIDO") {
            cartera
                .obtenerRestitucionInmuebleCartera(idCredito)
                .then(async (response: any) => {
                    if (response && response.isSuccess) {
                        const {
                            capital,
                            seguroVida,
                            seguroHogar,
                            interesCorriente,
                            interesMora,
                            capitalRemanente,
                            interesRemanente,
                            totalDeuda,
                        } = response.data;

                        setCapital(capital);
                        setSeguroVida(seguroVida);
                        setSeguroHogar(seguroHogar);
                        setInteresCorriente(interesCorriente);
                        setInteresMora(interesMora);
                        setCapitalRemanente(capitalRemanente);
                        setInteresRemanente(interesRemanente);
                        setTotalDeuda(totalDeuda);

                        form.setValue("capital", capital);
                        form.setValue("seguroVida", seguroVida);
                        form.setValue("seguroHogar", seguroHogar);
                        form.setValue("interesCorriente", interesCorriente);
                        form.setValue("interesMora", interesMora);
                        form.setValue("capitalRemanente", capitalRemanente);
                        form.setValue("interesRemanente", interesRemanente);
                        form.setValue("totalDeuda", totalDeuda);
                    }
                })
                .catch(() => {
                    toast("Error del sistema", { type: toast.TYPE.ERROR });
                });

        } 
        // else {
        //     toast("El crédito no tiene el estado RESTITUIDO, no se realizará la solicitud", { type: toast.TYPE.ERROR });
        // }
    };


    useEffect(() => {
        obtenerTiposCausalesInmueble();
    }, [idCredito, estadoCredito, idEstadoCredito, saldoCapital]);

    const [mostrarCuotas, setMostrarCuotas] = useState(false);
    
    return (
        <div>
            <Dialog
                fullScreen
                open={open}
                onClose={handleClose}
                aria-labelledby="form-dialog-title"
            >
                <CHPaper title="CREAR NOVEDAD">
                    <Grid container style={{ width: '80%', display: 'flex', margin: 'auto', marginTop: '90px' }} >
                        <Grid item xs={12} md={6} className={classes.column}>
                            <Controller
                                name="tipoNovedad"
                                control={form.control}
                                rules={{
                                    required: 'Este campo es requerido.',
                                }}
                                render={({
                                    field: { onChange, value },
                                    fieldState: { error },
                                }) => (
                                    <CHSelect
                                        error={!!error}
                                        label="Tipo de Novedad *"
                                        value={value}
                                        helperText={error ? error.message : null}
                                        readOnly={readOnly}
                                        onChange={(e) => {
                                            const id = e.target.value;
                                            const tipoNovedad = tipoNovedades.find((x: any) => x?.id === id)?.codigo;
                                            
                                            setMostrarCuotas(Boolean(id) && tipoNovedad === "REDIFERIDO");

                                            setMostrarCausal(
                                                tipoNovedad === "ACELERACION"
                                            );
                                            onChange(e);
                                        }}
                                        >
                                        <MenuItem value="">
                                            Seleccione un tipo de novedad
                                        </MenuItem>
                                        {
                                            tipoNovedades?.map(
                                                (option: any) => (
                                                    <MenuItem key={option.id}
                                                        value={option.id}
                                                        disabled={
                                                            option.codigo !== 'ACELERACION' &&
                                                            option.codigo !== 'RESTITUCIÓN INMUEBLE' &&
                                                            option.codigo !== 'REDIFERIDO' &&
                                                            option.codigo !== 'REESTRUCTURACION'
                                                        }
                                                    >
                                                        {option.nombre}
                                                    </MenuItem>
                                                )
                                            )
                                        }
                                    </CHSelect>
                                )}
                            />
                        </Grid>

                        {
                            mostrarCausal &&

                            <Grid item xs={12} md={6} className={classes.column} >
                                <Controller
                                    name="tipoCausal"
                                    control={form.control}
                                    rules={{
                                        required: 'Este campo es requerido.',
                                    }}
                                    render={({
                                        field: { onChange, value },
                                        fieldState: { error },
                                    }) => (
                                        <CHSelect
                                            error={!!error}
                                            label="Causal *"
                                            value={value || ""}
                                            readOnly={readOnly}
                                            helperText={error ? error.message : null}
                                            onChange={(value) => {
                                                onChange(value)
                                            }}>
                                            <MenuItem value="">
                                                Seleccione la causa de aceleración
                                            </MenuItem>
                                            {
                                                tiposCausales?.map(
                                                    (option: any) => (
                                                        <MenuItem key={option.id} value={option.id}>
                                                            {option.nombre}
                                                        </MenuItem>
                                                    )
                                                )
                                            }
                                        </CHSelect>
                                    )}
                                />
                            </Grid>
                        }

                        <Grid item xs={12} md={6} className={classes.column}>
                            <Controller
                                name="fechaNovedad"
                                control={form.control}
                                rules={{
                                    required: 'Este campo es requerido.'
                                }}
                                render={({
                                    field: { onChange, value },
                                    fieldState: { error },
                                }) => (
                                    <CHDatePicker
                                        label="Fecha novedad *"
                                        invalidDateMessage="Fecha no válida"
                                        error={!!error}
                                        value={value}
                                        readOnly={readOnly}
                                        InputProps={{ readOnly }}
                                        helperText={error?.message}
                                        InputLabelProps={{
                                            shrink: true,
                                        }}
                                        onChange={date => {
                                            onChange(date);
                                        }}
                                    />
                                )}
                            />
                        </Grid>

                        <Grid item xs={12} md={6} className={classes.column}>
                            <Controller
                                name="fechaFinalizacion"
                                control={form.control}
                                rules={{
                                    required: 'Este campo es requerido.',
                                }}
                                render={({
                                    field: { onChange, value },
                                    fieldState: { error },
                                }) => (
                                    <CHDatePicker
                                        error={!!error}
                                        invalidDateMessage="Fecha no válida"
                                        helperText={error?.message}
                                        label="Fecha de finalización *"
                                        value={value}
                                        readOnly={readOnly}
                                        InputProps={{ readOnly }}
                                        onChange={date => {
                                            onChange(date);
                                        }}
                                    />
                                )}
                            />
                        </Grid>

                        <Typography className={classes.titleform} variant="h5" component="h6">
                            Saldo de la obligación
                        </Typography>

                        <Grid container>
                            <Grid className={classes.column} item xs={12} md={3}>
                                <Controller
                                    name="seguroVida"
                                    control={form.control}
                                    rules={{
                                        required: 'Este campo es requerido.'
                                    }}
                                    render={({
                                        field: { onChange, value },
                                        fieldState: { error },
                                    }) => (
                                        <CHTextField
                                            error={!!error}
                                            helperText={error?.message}
                                            isReadOnly
                                            inputProps={{
                                                style: {
                                                    textAlign: 'right',
                                                },
                                                className: classes.input
                                            }}
                                            label="Seguro de vida"
                                            value={Math.round(value || seguroVida || productoData?.acumuladoSeguroVida || 0)}
                                            onChange={onChange}
                                            pesosEnterosMask
                                            InputLabelProps={{ shrink: true }}
                                        />
                                    )}
                                />

                            </Grid>

                            <Grid className={classes.column} item xs={12} md={3}>
                                <Controller
                                    name="seguroHogar"
                                    control={form.control}
                                    rules={{
                                        required: 'Este campo es requerido.'
                                    }}
                                    render={({
                                        field: { onChange, value },
                                        fieldState: { error },
                                    }) => (
                                        <CHTextField
                                            error={!!error}
                                            helperText={error?.message}
                                            isReadOnly
                                            inputProps={{
                                                style: {
                                                    textAlign: 'right',
                                                },
                                                className: classes.input
                                            }}
                                            label="Seguro de hogar"
                                            value={Math.round(value || seguroHogar || productoData?.acumuladoSeguroHogar || 0)}
                                            onChange={onChange}
                                            pesosEnterosMask
                                            InputLabelProps={{ shrink: true }}
                                        />
                                    )}
                                />
                            </Grid>

                            <Grid className={classes.column} item xs={12} md={3}>
                                <Controller
                                    name="capital"
                                    control={form.control}
                                    rules={{
                                        required: 'Este campo es requerido.'
                                    }}
                                    render={({
                                        field: { onChange, value },
                                        fieldState: { error },
                                    }) => (
                                        <CHTextField
                                            error={!!error}
                                            helperText={error?.message}
                                            isReadOnly
                                            inputProps={{
                                                style: {
                                                    textAlign: 'right',
                                                },
                                                className: classes.input
                                            }}
                                            label="Capital"
                                            value={capital || saldoCapital || productoData?.saldoCapital || 0}
                                            onChange={onChange}
                                            pesosEnterosMask
                                            InputLabelProps={{ shrink: true }}
                                        />
                                    )}
                                />
                            </Grid>

                            <Grid className={classes.column} item xs={12} md={3}>
                                <Controller
                                    name="interesCorriente"
                                    control={form.control}
                                    rules={{
                                        required: 'Este campo es requerido.'
                                    }}
                                    render={({
                                        field: { onChange, value },
                                        fieldState: { error },
                                    }) => (
                                        <CHTextField
                                            error={!!error}
                                            helperText={error?.message}
                                            isReadOnly
                                            inputProps={{
                                                style: {
                                                    textAlign: 'right',
                                                },
                                                className: classes.input
                                            }}
                                            label="Interes Corrientes"
                                            value={Math.round(Number(interesCorriente) || 0)}
                                            onChange={onChange}
                                            pesosEnterosMask
                                            InputLabelProps={{ shrink: true }}
                                        />
                                    )}
                                />
                            </Grid>

                            <Grid className={classes.column} item xs={12} md={3}>
                                <Controller
                                    name="interesMora"
                                    control={form.control}
                                    rules={{
                                        required: 'Este campo es requerido.'
                                    }}
                                    render={({
                                        field: { onChange, value },
                                        fieldState: { error },
                                    }) => (
                                        <CHTextField
                                            error={!!error}
                                            helperText={error?.message}
                                            isReadOnly
                                            inputProps={{
                                                style: {
                                                    textAlign: 'right',
                                                },
                                                className: classes.input
                                            }}
                                            label="Intereses de mora"
                                            value={Math.round(value || interesMora || productoData?.acumuladoInteresMora || 0)}
                                            onChange={onChange}
                                            pesosEnterosMask
                                            InputLabelProps={{ shrink: true }}
                                        />
                                    )}
                                />
                            </Grid>

                            {
                                (producto.idTipoCredito === 1) &&
                                <>
                                    <Grid className={classes.column} item xs={12} md={3}>
                                        <Controller
                                            name="capitalRemanente"
                                            control={form.control}
                                            rules={{
                                                required: 'Este campo es requerido.'
                                            }}
                                            render={({
                                                field: { onChange, value },
                                                fieldState: { error },
                                            }) => (
                                                <CHTextField
                                                    error={!!error}
                                                    helperText={error?.message}
                                                    isReadOnly
                                                    inputProps={{
                                                        style: {
                                                            textAlign: 'right',
                                                        },
                                                        className: classes.input
                                                    }}
                                                    label="Capital Remanente"
                                                    value={capitalRemanente || productoData?.capitalRemanenteCorte || 0}
                                                    onChange={onChange}
                                                    pesosEnterosMask
                                                    InputLabelProps={{ shrink: true }}
                                                />
                                            )}
                                        />
                                    </Grid>

                                    <Grid className={classes.column} item xs={12} md={3}>
                                        <Controller
                                            name="interesRemanente"
                                            control={form.control}
                                            rules={{
                                                required: 'Este campo es requerido.'
                                            }}
                                            render={({
                                                field: { onChange, value },
                                                fieldState: { error },
                                            }) => (
                                                <CHTextField
                                                    error={!!error}
                                                    helperText={error?.message}
                                                    isReadOnly
                                                    inputProps={{
                                                        style: {
                                                            textAlign: 'right',
                                                            boxSizing: 'border-box'
                                                        },
                                                        className: classes.input
                                                    }}
                                                    label="Interés Remanente"
                                                    value={Math.round(interesRemanente || productoData?.interesesRemanenteCorte || 0)}
                                                    onChange={onChange}
                                                    pesosEnterosMask
                                                    InputLabelProps={{ shrink: true }}
                                                />
                                            )}
                                        />
                                    </Grid>

                                </>
                            }

                            <Grid className={classes.column} item xs={12} md={3}>
                                <Controller
                                    name="totalDeuda"
                                    control={form.control}
                                    rules={{
                                        required: 'Este campo es requerido.'
                                    }}
                                    render={({
                                        field: { onChange, value },
                                        fieldState: { error },
                                    }) => (
                                        <CHTextField
                                            error={!!error}
                                            helperText={error?.message}
                                            isReadOnly
                                            inputProps={{
                                                style: {
                                                    textAlign: 'right',
                                                },
                                                className: classes.input
                                            }}
                                            label="Total deuda"
                                            value={Math.round(totalDeuda || productoData?.saldoTotalCorte || 0)}
                                            onChange={onChange}
                                            pesosEnterosMask
                                            InputLabelProps={{ shrink: true }}
                                        />
                                    )}
                                />
                            </Grid>

                            {mostrarCuotas && (
                                <Grid className={classes.column} item xs={12} md={3}>
                                    <Controller
                                        name="cuotaCredito"
                                        control={form.control}
                                        render={({
                                            field: { onChange, value },
                                            fieldState: { error },
                                        }) => (
                                            <CHTextField
                                                onChange={onChange}
                                                label="Número de Cuotas"
                                                type="number"
                                                value={value}
                                                error={!!error}
                                                helperText={error ? error.message : null}
                                                fullWidth
                                            />
                                        )}
                                    />
                                </Grid>
                            )}
                        </Grid>

                        {
                            readOnly &&
                            <>
                                <Typography className={classes.titleform} variant="h5" component="h6">
                                    Estado de la novedad
                                </Typography>

                                <Grid container>
                                    <Grid item xs={12} md={6} className={classes.column}  >
                                        <Controller
                                            name="estado"
                                            control={form.control}
                                            render={({
                                                field: { onChange, value },
                                                fieldState: { error },
                                            }) => (
                                                <CHSelect
                                                    readOnly
                                                    label="Estado"
                                                    value={value || ""}
                                                    onChange={(value) => {
                                                        onChange(value)
                                                    }}>
                                                    <MenuItem value="">
                                                        Seleccione un estado de novedad
                                                    </MenuItem>
                                                    {
                                                        estadosNovedades?.map(
                                                            (option: any) => (
                                                                <MenuItem
                                                                    key={option.id}
                                                                    value={option.id}
                                                                >
                                                                    {option.nombre}
                                                                </MenuItem>
                                                            )
                                                        )}

                                                </CHSelect>
                                            )}
                                        />
                                    </Grid>
                                    <Grid className={classes.column} item xs={12} md={6}>
                                        <Controller
                                            name="valorPagado"
                                            control={form.control}
                                            render={({
                                                field: { onChange, value },
                                                fieldState: { error },
                                            }) => (
                                                <CHTextField
                                                    error={!!error}
                                                    helperText={error?.message}
                                                    isReadOnly
                                                    inputProps={{
                                                        style: {
                                                            textAlign: 'right',
                                                        },
                                                        className: classes.input
                                                    }}
                                                    label="Valor Pagado"
                                                    value={value}
                                                    onChange={onChange}
                                                    pesosEnterosMask
                                                    InputLabelProps={{ shrink: true }}
                                                />
                                            )}
                                        />
                                    </Grid>
                                </Grid>
                            </>
                        }

                        <Grid container>
                            <Grid item style={{ marginTop: '100px' }}>
                                {
                                    !readOnly &&
                                    <Button
                                        size="small"
                                        variant="contained"
                                        color="primary"
                                        style={{ marginRight: "20px" }}
                                        onClick={() => {
                                            form.handleSubmit((data) => {
                                                data.cuotaCredito = Number(form.watch('cuotaCredito'));
                                                handleSubmit(data);
                                            })();
                                        }}>
                                        GUARDAR
                                    </Button>
                                }
                                <Button
                                    size="small"
                                    variant="contained"
                                    color="default"
                                    onClick={handleClose}
                                >
                                    ATRÁS
                                </Button>
                            </Grid>
                        </Grid>

                    </Grid>
                </CHPaper>
            </Dialog>
        </div>
    );
};
