import React from "react"
import { Delete, Edit, Visibility } from "@material-ui/icons";
import { createStyles, Grid, IconButton, makeStyles, Paper, Table, TableBody, TableCell, TableContainer, TableHead, TableRow } from "@material-ui/core";
import { MatriculaInmobiliariaModel } from "../../../../models/matricula-inmobiliaria.model";


const useStyles = makeStyles(() =>
    createStyles({
        columnButtonAdd: {
            textAlign: 'right',
        },
    }),
);

const TablaInformacionDelInmueble = (
    {
        matriculaInmobiliariaModel,
        siEsAprobadaSolcitud,
        responseSolicitud,
        seleccionarRegistro,
        eliminarRegistro,
        campoSoloLecturaRadicacionAprobada,
    }: {
        matriculaInmobiliariaModel: any
        siEsAprobadaSolcitud: any
        responseSolicitud: any
        seleccionarRegistro: any
        eliminarRegistro: any
        campoSoloLecturaRadicacionAprobada: boolean;
    }) => {

    const classes = useStyles();

    return (

        <>
            <h3>Lista de matrículas inmobiliarias </h3>
            <TableContainer component={Paper}>
                <Grid
                    className={classes.columnButtonAdd}
                    item
                    xs={12}
                    md={12}
                >
                    <Table aria-label="simple table">
                        <TableHead>
                            <TableRow>
                                <TableCell>Número Matrícula</TableCell>
                                <TableCell>Estado</TableCell>
                                <TableCell>Dirección</TableCell>
                                <TableCell>Departamento</TableCell>
                                <TableCell>Ciudad</TableCell>
                                {
                                    (((siEsAprobadaSolcitud || responseSolicitud?.secciones?.includes('INCONSISTENCIA')) && responseSolicitud?.soL_RECHAZADA !== '1')) || campoSoloLecturaRadicacionAprobada ?
                                    null :
                                    <TableCell align="center">
                                        Acciones
                                    </TableCell>
                               }
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {matriculaInmobiliariaModel.map(
                                (option: MatriculaInmobiliariaModel) => (
                                    <TableRow key={option.numeroMatricula}>
                                        <TableCell>
                                            <span>{option.numeroMatricula}</span>
                                        </TableCell>
                                        <TableCell>
                                            {option.esPrincipal ? 'Principal' : 'Relacionado'}
                                        </TableCell>
                                        <TableCell>
                                            {option.direccion}
                                        </TableCell>
                                        <TableCell>
                                            {option.departamento.descripcion}
                                        </TableCell>
                                        <TableCell>
                                            {option.ciudad.descripcion}
                                        </TableCell>
                                        <TableCell align="center">
                                            {
                                                (((siEsAprobadaSolcitud || responseSolicitud?.secciones?.includes('INCONSISTENCIA')) && responseSolicitud?.soL_RECHAZADA !== '1')) || campoSoloLecturaRadicacionAprobada ?
                                                   null : <IconButton
                                                        aria-label="Editar"
                                                        color="primary"
                                                        onClick={() => {
                                                            seleccionarRegistro(
                                                                option,
                                                            );
                                                        }}
                                                    >
                                                        <Edit />
                                                    </IconButton>
                                            }
                                            {
                                                ((siEsAprobadaSolcitud || responseSolicitud?.secciones?.includes('INCONSISTENCIA')) && responseSolicitud?.soL_RECHAZADA !== '1') || campoSoloLecturaRadicacionAprobada ?
                                                    '' :
                                                    <IconButton
                                                        aria-label="Eliminar"
                                                        color="secondary"
                                                        onClick={() => {
                                                            eliminarRegistro(
                                                                option.numeroMatricula,
                                                            );
                                                        }}
                                                    >
                                                        <Delete />
                                                    </IconButton>
                                            }
                                        </TableCell>
                                    </TableRow>
                                ),
                            )}
                        </TableBody>
                    </Table>
                </Grid>
            </TableContainer>
        </>
    )
}

export default TablaInformacionDelInmueble