import React, { ChangeEvent, useEffect, useState } from 'react';
import { connect } from 'react-redux';
import {
    Button,
    Grid,
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableRow,
} from '@material-ui/core';
import moment from 'moment';
import CheckIcon from '@material-ui/icons/Check';
import { createStyles, makeStyles, Theme } from '@material-ui/core/styles';
import { toast } from 'react-toastify';
import CHLoadingProcess from '../ch-loading-process/CHLoadingProcess';
import CHPaper from '../ch-paper/CHPaper';
import { AppState } from '../../store/rootReducer';
import { startPostCreditFlowDocuments } from '../../actions/credit.actions';
import { CreditFlowDocumentsRequestModel } from '../../models/requests/credit-flow-documents-request.model';
import { ProcedureRequestModel } from '../../models/procedure-request.model';
import { CreditFlowDocumentModel } from '../../models/credit-flow-document.model';
import CreditApi from '../../services/api-credit.service';
import CHFileUploader from '../ch-file-uploader/CHFileUploader';
import AuthService from '../../services/auth.service';
import NotificationService from '../../services/notification.service';
import UtilService from '../../utils/util.service';
import { CreditBasicDataModel } from '../../models/credit-basic-data.model';
import CHCheckbox from '../ch-checkbox/CHCheckbox';
import { LoadingComponent } from '../loading/loading.component';


const api = CreditApi();

const useStyles = makeStyles((theme: Theme) =>
    createStyles({
        checkContainer: {
            width: '100%',
            display: 'flex',
            alignItems: 'center',
            color: theme.palette.success.main,
        },
    }),
);

function RequestInformationUploadFiles({
    typeRequest,
    procedureRequest,
    creditFlowDocumentsData,
    creditBasicData,
    docObligatorio,
    isLoading
}: {
    typeRequest?: string;
    procedureRequest: ProcedureRequestModel;
    creditFlowDocumentsData: CreditFlowDocumentModel[];
    creditBasicData: CreditBasicDataModel;
    docObligatorio: any;
    isLoading: boolean;
}) {
    const classes = useStyles();
    const [filesUploaded, setFilesUploaded] = useState<number[]>([]);
    const [isLoadingFile, setIsLoadingFile] = useState<boolean>(false);
    const [listaArchivosMostrar, setListasArchivosMostrar] = useState<any[]>([]);
    const [documentosSeguros, setDocumentosSeguros] = useState<any[]>([]);
    const [documentosVendedor, setDocumentosVendedor] = useState<any[]>([]);
    const [documentosInmueble, setDocumentosInmueble] = useState<any[]>([]);
    const [documentosAfiliado, setDocumentosAfiliado] = useState<any[]>([]);
    
    const [rutaImagen, setRutaImagen] = useState<any[]>([]);
    const user = AuthService.getUserInfo();


    useEffect(() => {
       
        const mensaje="sin datos"

        listarArchivos();
    }, [filesUploaded, setFilesUploaded])
    
    const listarArchivos = async () => {
        
        const request: CreditFlowDocumentsRequestModel = {
            tcR_ID: procedureRequest.creditTypeID,
            orden: procedureRequest.order,
            principal: procedureRequest.principalActivity,
            soC_ID: procedureRequest.requestID,
            afL_ID: procedureRequest.flowActivityID,
        };

        await api
        
            .postCreditFiles(request) 
            .then(async response => {

                
                if (response) { 
                    
                                            
                    const docOrdenF = [...response.data.filter((x:any) => x.obligatorio === 'S'),...response.data.filter((x:any) => x.obligatorio === 'N')]
                    
                    

                    const docSeguro = docOrdenF.filter((x:any) => x.tdC_ID === 65 || x.tdC_ID === 64 
                    || x.tdC_ID === 21 || x.tdC_ID === 20 || x.tdC_ID === 23 || x.tdC_ID === 24   
                    || x.tdC_ID === 5 || x.tdC_ID === 75 || x.tdC_ID === 159 || x.tdC_ID === 170)                    
                    setDocumentosSeguros(docSeguro)

                    const docVendedor = docOrdenF.filter((x:any) => x.tdC_ID === 66 || x.tdC_ID === 67
                    || x.tdC_ID === 15 || x.tdC_ID === 16)
                    setDocumentosVendedor(docVendedor)
                    
                    const docInmueble = docOrdenF.filter((x:any) => x.tdC_ID === 9 || x.tdC_ID === 61
                    || x.tdC_ID === 6 || x.tdC_ID === 10 || x.tdC_ID === 11 || x.tdC_ID === 12 || x.tdC_ID === 13
                    || x.tdC_ID === 130 || x.tdC_ID === 131 || x.tdC_ID === 115 || x.tdC_ID === 78 || x.tdC_ID === 160
                    || x.tdC_ID === 108)
                    setDocumentosInmueble(docInmueble)

                    const docAfiliado = docOrdenF.filter((x:any) => 
                    x.tdC_ID !== 9 &&  x.tdC_ID !== 67
                    && x.tdC_ID !== 61 &&  x.tdC_ID !== 64 &&  x.tdC_ID !== 65 && x.tdC_ID !== 66
                    && x.tdC_ID !== 21 && x.tdC_ID !== 20 && x.tdC_ID !== 23 && x.tdC_ID !== 24 && x.tdC_ID !== 6
                    && x.tdC_ID !== 10 && x.tdC_ID !== 11 && x.tdC_ID !== 12 && x.tdC_ID !== 13 && x.tdC_ID !== 15
                    && x.tdC_ID !== 16 && x.tdC_ID !== 5 && x.tdC_ID !== 130 && x.tdC_ID !== 131 && x.tdC_ID !== 115
                    && x.tdC_ID !== 75 && x.tdC_ID !== 170 && x.tdC_ID !== 108 && x.tdC_ID !== 160 && x.tdC_ID !== 78 )
                    setDocumentosAfiliado(docAfiliado)

                                    
                    if (response.isSuccess) {
                        setListasArchivosMostrar(response.data)
                                                
                        docObligatorio (response.data);
                        
                    } else {
                        await NotificationService.genericAlert(
                            'Error en actualización',
                            'Ocurrio un error al intentar actualizar, intente de nuevo.',
                            'error',
                        );
                        
                    }
                }
            })
            .catch(() => {
                
                toast('Error del sistema', { type: toast.TYPE.ERROR });
            });

    }

    const datos = {
        reporte: 'REPORTE_HABERES',
        clienteIdentificacion:
        procedureRequest.clientIdentificationNumber.toString(),
        cuentaId: 0,
    };

    const datosFiRiesgo = {
        idSolicitud: procedureRequest.requestID,
        nombreSolicitante: `${user.USR_NOMBRE}${user.USR_SEGUNDONOMBRE}${user.USR_APELLIDO}${user.USR_SEGUNDOAPELLIDO}`,
        idSolicitante: user.USR_IDENTIFICACION,
    };

    const datosLeasing: any = {
        idSolicitud: procedureRequest.requestID,
    };


    const getFileLeasing = (path: string) => async () => {
        try {
            setIsLoadingFile(true);
            const data = await api.postCreditDownloadFileLeasing(datosLeasing);
            const ext = UtilService.getFileExtension(path);
            if (ext) {
                const mimeType = UtilService.getMimeTypeFromExtension(ext);
                if (mimeType) {
                    const file = new Blob([data], { type: mimeType });
                    const fileURL = URL.createObjectURL(file);
                    window.open(fileURL);
                }
            }
            setIsLoadingFile(false);
        } catch (e) {
            await NotificationService.genericAlert(
                'Advertencia',
                'No se puede generar archivo para este Usuario.',
                'warning',
            );
            setIsLoadingFile(false);
        }
    };

    const getFileS = (path: string) => async () => {
    
        if (path === '\\Reporte_Comercial.pdf') {
            const request = {
                idType: creditBasicData.tidID,
                idNumber: procedureRequest.clientIdentificationNumber,
            };
            try {
                setIsLoadingFile(true);
                const data = await api.postObtenerHistorialComercialBuro(
                    request,
                );
                const ext = UtilService.getFileExtension(path);
                if (ext) {
                    const mimeType = UtilService.getMimeTypeFromExtension(ext);
                    if (mimeType) {
                        const file = new Blob([data], { type: mimeType });
                        const fileURL = URL.createObjectURL(file);

                        window.open(fileURL);
                    }
                }
                setIsLoadingFile(false);
            } catch (e) {
                await NotificationService.genericAlert(
                    'Advertencia',
                    'No se puede generar archivo  para este Usuario.',
                    'warning',
                );
                setIsLoadingFile(false);
            }
        } else {
            try {
                setIsLoadingFile(true);
                const data = await api.postCreditDownloadFileS(path);
                const ext = UtilService.getFileExtension(path);
                if (ext) {
                    const mimeType = UtilService.getMimeTypeFromExtension(ext);
                    if (mimeType) {
                        const file = new Blob([data], { type: mimeType });
                        const fileURL = URL.createObjectURL(file);
                        window.open(fileURL);
                    }
                }
                setIsLoadingFile(false);
            } catch (e) {
                await NotificationService.genericAlert(
                    'Advertencia',
                    'No se puede generar archivo para este Usuario.',
                    'warning',
                );
                setIsLoadingFile(false);
            }
        }
    };

    const getFile = (path: string) => async () => {
        try {
            setIsLoadingFile(true);
            const data = await api.postCreditDownloadFile(datos);
            const ext = UtilService.getFileExtension(path);
            if (ext) {
                const mimeType = UtilService.getMimeTypeFromExtension(ext);
                if (mimeType) {
                    const file = new Blob([data], { type: mimeType });
                    const fileURL = URL.createObjectURL(file);
                    window.open(fileURL);
                }
            }
            setIsLoadingFile(false);
        } catch (e) {
            await NotificationService.genericAlert(
                'Advertencia',
                'No se puede generar archivo para este Usuario.',
                'warning',
            );
            setIsLoadingFile(false);
        }
    };

    const getFileReporteFiRiesgo = (path: string) => async () => {
        try {
            setIsLoadingFile(true);

            const data = await api.postCreditDownloadFileFiRiesgo(
                datosFiRiesgo,
            );
            const ext = UtilService.getFileExtension(path);
            if (ext) {
                const mimeType = UtilService.getMimeTypeFromExtension(ext);
                if (mimeType) {
                    const file = new Blob([data], { type: mimeType });
                    const fileURL = URL.createObjectURL(file);

                    window.open(fileURL);
                }
            }
            setIsLoadingFile(false);
        } catch (e) {
            await NotificationService.genericAlert(
                'Advertencia',
                'No se puede generar archivo  para este Usuario.',
                'warning',
            );
            setIsLoadingFile(false);
        }
    };


    // if (isLoading || isLoadingFile) {
    //     return <CHLoadingProcess />;
    // }


    const uploadFile = (id: any) => (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files != null) {
           
            setIsLoadingFile(true);
            const file = e.target.files[0];
            const formData = new FormData();
            if (file.type === 'application/pdf') {
                formData.append('request', file);
                api.postCreditUploadDocument(formData)
                    .then(res => {
                        if (res.isSuccess) {
                            const path = res.data;
                            const user = AuthService.getUserInfo();
                            const data = {
                                creadoPor: user.USR_ID,
                                idSolicitudCredito: procedureRequest.requestID,
                                idTipoDocumento: id,
                                rutaImagen: path,
                                fechaCreacion: moment().format(),
                            };
                            api.postCreditCreateDocument(data)
                                .then(() => {
                                    setFilesUploaded(oldFiles => [
                                        ...oldFiles,
                                        id,
                                    ]);
                                    setIsLoadingFile(false);
                                    return NotificationService.genericAlert(
                                        'Archivo Subido',
                                        'Se subio correctamente el archivo al servidor',
                                    );
                                })
                                .catch(async () => {
                                    setIsLoadingFile(false);
                                    await NotificationService.genericAlert(
                                        'Error',
                                        'No se pudo subir el archivo al servidor. Intente nuevamente',
                                        'error',
                                    );
                                });
                        }
                    })
                    .catch(() => setIsLoadingFile(false));
            } else {
                NotificationService.genericAlert(
                    'Error',
                    'Solo se permite cargar archivos PDF',
                    'error',
                );
                setIsLoadingFile(false);
            }
        }
    };



    const actualizarEstado = async (e: React.ChangeEvent<HTMLInputElement>, file: any) => {

        if(!file.rutA_IMAGEN){
            await NotificationService.genericAlert(
                'Error en la verificacón',
                'Se debe cargar un documento antes de la verificación.',
                'error',
            );
            return
        }

        setIsLoadingFile(true)
        const isChecked = e.target.checked;  
        const valorNumerico = Number(isChecked);  
        const request = {
            dcS_APROBACION: valorNumerico,
            dcS_RUTA_IMAGEN: file.rutA_IMAGEN,
            soC_ID: procedureRequest.requestID
        }


        api.postActualizaDocumentoLegalizacion(request)
        .then(response =>  {
            if(response.isSuccess){
                listarArchivos()
            }
        })
        .catch(async() => {
                setIsLoadingFile(false)
                await NotificationService.genericAlert(
                    'Error',
                    'No se pudo actualizar el archivo. Intente nuevamente',
                    'error',
                )
            })
        .finally(() => setIsLoadingFile(false));

    };


    return (
        <>    
            <LoadingComponent key="loader" loading={isLoading || isLoadingFile} />


            {documentosAfiliado.length !== 0 && ( 
            <CHPaper title="Documentos Afiliado">
                <Table size="small">
                    <TableHead>
                        <TableRow>
                            
                            <TableCell component="th">
                                Documento
                            </TableCell>
                            <TableCell component="th">
                                    Obligatorio
                            </TableCell>
                            <TableCell component="th">Acción</TableCell>
                            <TableCell component="th">
                                Ver Archivo
                            </TableCell>
                            {procedureRequest.flowActivityID === 16 && (
                                <TableCell component="th">
                                    Aprobación
                                </TableCell>
                            )}
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {documentosAfiliado.map(
                            (file, key) => (
                                <TableRow key={`file-${key}`}>

                                    <TableCell style = {{width:"65%"}} >{file.tipO_DOCUMENTO}</TableCell>
                                    <TableCell style = {{width:"10%"}} >{file.obligatorio === 'S'? "SI":"NO"}</TableCell>
                        
                                    <TableCell>
                                        <CHFileUploader
                                            file={file}
                                            filesUploaded={filesUploaded}
                                            id={file.tdC_ID}
                                            onChangeInput={uploadFile}
                                        />
                                        {/* {file.cargado === false ? (
                                            */}
                                    </TableCell>
                                    <TableCell>
                                        { (file.rutA_IMAGEN !== null && file.visualiza) && (
                                        <Button onClick={getFileS(file.rutA_IMAGEN)}>
                                            Ver
                                        </Button>
                                        )}
                                    </TableCell>
                                    {procedureRequest.flowActivityID === 16 && (

                                    <TableCell component="th">
                                        <CHCheckbox
                                            label=" "
                                            onChange={(e) => actualizarEstado(e, file)
                                            }
                                            checked={file.dcS_APROBACION === 1}
                                            />
                                    </TableCell>
                                    )}
                                </TableRow>
                            ),
                        )}
                    </TableBody>
                </Table>
            </CHPaper>
            )}
            {documentosSeguros.length !== 0 && ( 
            <CHPaper title="Documentos Seguros">
                <Table size="small">
                    <TableHead>
                        <TableRow>
                            
                            <TableCell component="th">
                                Documento
                            </TableCell>
                            <TableCell component="th">
                                    Obligatorio
                            </TableCell>
                            <TableCell component="th">Acción</TableCell>
                            <TableCell component="th">
                                Ver Archivo
                            </TableCell>
                            {procedureRequest.flowActivityID === 16 && (
                                <TableCell component="th">
                                    Aprobación
                                </TableCell>
                            )}
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {documentosSeguros.map(
                            (file, key) => (
                                <TableRow key={`file-${key}`}>

            
                    

                    <TableCell style = {{width:"65%"}} >{file.tipO_DOCUMENTO}</TableCell>
                    <TableCell style = {{width:"10%"}} >{file.obligatorio === 'S'? "SI":"NO"}</TableCell>
        
                                    <TableCell>
                                        <CHFileUploader
                                            file={file}
                                            filesUploaded={filesUploaded}
                                            id={file.tdC_ID}
                                            onChangeInput={uploadFile}
                                        />
                                        {/* {file.cargado === false ? (
                                            */}
                                    </TableCell>
                                    <TableCell>
                                        { (file.rutA_IMAGEN !== null && file.visualiza) && (
                                        <Button onClick={getFileS(file.rutA_IMAGEN)}>
                                            Ver
                                        </Button>
                                        )}
                                    </TableCell>
                                    {procedureRequest.flowActivityID === 16 && (

                                    <TableCell component="th">
                                        <CHCheckbox
                                            label=" "
                                            onChange={(e) => actualizarEstado(e, file)
                                            }
                                            checked={file.dcS_APROBACION === 1}
                                            />
                                    </TableCell>
                                    )}
                                </TableRow>
                            ),
                        )}
                    </TableBody>
                </Table>
            </CHPaper>
            )}
            {documentosVendedor.length !== 0 && ( 
            <CHPaper title="Documentos Vendedor">
                <Table size="small">
                    <TableHead>
                        <TableRow>
                            
                            <TableCell component="th">
                                Documento
                            </TableCell>
                            <TableCell component="th">
                                    Obligatorio
                            </TableCell>
                            <TableCell component="th">Acción</TableCell>
                            <TableCell component="th">
                                Ver Archivo
                            </TableCell>
                            {procedureRequest.flowActivityID === 16 && (
                                <TableCell component="th">
                                    Aprobación
                                </TableCell>
                            )}
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {documentosVendedor.map(
                            (file, key) => (
                                <TableRow key={`file-${key}`}>

            
                    

                                    <TableCell style = {{width:"65%"}} >{file.tipO_DOCUMENTO}</TableCell>
                                    <TableCell style = {{width:"10%"}} >{file.obligatorio === 'S'? "SI":"NO"}</TableCell>
                        
                                    <TableCell>
                                        <CHFileUploader
                                            file={file}
                                            filesUploaded={filesUploaded}
                                            id={file.tdC_ID}
                                            onChangeInput={uploadFile}
                                        />
                                        {/* {file.cargado === false ? (
                                            */}
                                    </TableCell>
                                    <TableCell>
                                        { (file.rutA_IMAGEN !== null && file.visualiza) && (
                                        <Button onClick={getFileS(file.rutA_IMAGEN)}>
                                            Ver
                                        </Button>
                                        )}
                                    </TableCell>
                                    {procedureRequest.flowActivityID === 16 && (

                                    <TableCell component="th">
                                        <CHCheckbox
                                            label=" "
                                            onChange={(e) => actualizarEstado(e, file)
                                            }
                                            checked={file.dcS_APROBACION === 1}
                                            />
                                    </TableCell>
                                    )}
                                </TableRow>
                            ),
                        )}
                    </TableBody>
                </Table>
            </CHPaper>
            )}
            {documentosInmueble.length !== 0 && ( 
            <CHPaper title="Documentos Inmueble">
                <Table size="small">
                    <TableHead>
                        <TableRow>
                            
                            <TableCell component="th">
                                Documento
                            </TableCell>
                            <TableCell component="th">
                                    Obligatorio
                            </TableCell>
                            <TableCell component="th">Acción</TableCell>
                            <TableCell component="th">
                                Ver Archivo
                            </TableCell>
                            {procedureRequest.flowActivityID === 16 && (
                                <TableCell component="th">
                                    Aprobación
                                </TableCell>
                            )}
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {documentosInmueble.map(
                            (file, key) => (
                                <TableRow key={`file-${key}`}>

            
                    

                    <TableCell style = {{width:"65%"}} >{file.tipO_DOCUMENTO}</TableCell>
                    <TableCell style = {{width:"10%"}} >{file.obligatorio === 'S'? "SI":"NO"}</TableCell>
        
                                    <TableCell>
                                        <CHFileUploader
                                            file={file}
                                            filesUploaded={filesUploaded}
                                            id={file.tdC_ID}
                                            onChangeInput={uploadFile}
                                        />
                                        {/* {file.cargado === false ? (
                                            */}
                                    </TableCell>
                                    <TableCell>
                                        { (file.rutA_IMAGEN !== null && file.visualiza) && (
                                        <Button onClick={getFileS(file.rutA_IMAGEN)}>
                                            Ver
                                        </Button>
                                        )}
                                    </TableCell>
                                    {procedureRequest.flowActivityID === 16 && (

                                    <TableCell component="th">
                                        <CHCheckbox
                                            label=" "
                                            onChange={(e) => actualizarEstado(e, file)
                                            }
                                            checked={file.dcS_APROBACION === 1}
                                            />
                                    </TableCell>
                                    )}
                                </TableRow>
                            ),
                        )}
                    </TableBody>
                </Table>
            </CHPaper>
            )}

        </>
    );
}

const mapStateToProps = (state: AppState) => ({
    // isLoading: state.credit.loading,
    creditFlowDocumentsData: state.credit.creditFlowDocumentsData,
    creditBasicData: state.credit.creditBasicData,
});

const mapDispatchToProps = {
    startPostCreditFlowDocuments,
};

export default connect(
    mapStateToProps,
    mapDispatchToProps,
)(RequestInformationUploadFiles);
