import { createStyles, Grid, makeStyles } from '@material-ui/core';
import React from 'react';
import { Controller, UseFormReturn } from 'react-hook-form';
import CHPaper from '../../../components/ch-paper/CHPaper';
import CHTextField from '../../../components/ch-text-field/CHTextField';
import UtilService from '../../../utils/util.service';

const useStyles = makeStyles(() =>
	createStyles({
		column: {
			padding: '10px',
			textAlign: 'center',
		},
	}),
);

const CuadrosAfectados = (props: Props) => {

    const classes = useStyles();
    const {formularioCuadrosAfectados} = props;

    const dataPrueba = [{
        cuadro: '6181',
        tipoVivienda: 'Nueva Individual',
        monto: 10000000,
        cantidad: 1
    }]

    return (
        <CHPaper title="Cuadros Consolidados Afectados">
             <Grid container>
             <table className="credit-table"    
                    style={{
                        margin: '10px',
                        width: '99%',
                    }}>
                    <thead>
                    <tr>
                        <th style={{ textAlign: 'center', width: '20%' }}>
                           Cuadro
                        </th>
                        <th style={{ textAlign: 'center' }}>
                           Tipo de Vivienda
                        </th>
                        <th style={{ textAlign: 'center' }}>
                           Monto
                        </th>
                        <th style={{ textAlign: 'center', width: '20%' }}>
                           Cantidad Subsidios
                        </th>
                    </tr>
                </thead>
                <tbody>
					{dataPrueba?.map((row: any, index: any) => (
						<tr key={`table-${index}`}>
							<td>{row.cuadro}</td>
							<td>{row?.tipoVivienda}</td>
							<td>{UtilService.formatCurrency(row?.monto)}</td>
                            <td>{row?.cantidad}</td>
						</tr>
					))}
				</tbody>
           </table> 
          </Grid> 
          <Grid container>
            <Grid className={classes.column} item xs={12} md={3}>   
                    <Controller
                        name="totalSubsidios"
                        control={formularioCuadrosAfectados.control}
                        render={({ field: { onChange, value } }) => (
                            <CHTextField
                                isReadOnly
                                value={value}
                                onChange={onChange}
                                label="Total Subsidios"
                                InputLabelProps={{ shrink: true }}
                            />
                        )}
                    />
            </Grid>
          </Grid>  
          <Grid container>
            <Grid className={classes.column} item xs={12} md={3}>   
                    <Controller
                        name="totalMonto"
                        control={formularioCuadrosAfectados.control}
                        render={({ field: { onChange, value } }) => (
                            <CHTextField
                                isReadOnly
                                currencyMask
                                value={value}
                                onChange={onChange}
                                label="Total Monto"
                                InputLabelProps={{ shrink: true }}
                            />
                        )}
                    />
            </Grid>
          </Grid> 
          <Grid container>
            <Grid className={classes.column} item xs={12} md={3}>   
                    <Controller
                        name="fechaAdjudicacion"
                        control={formularioCuadrosAfectados.control}
                        render={({ field: { onChange, value } }) => (
                            <CHTextField
                                isReadOnly
                                value={value}
                                onChange={onChange}
                                label="Fecha Adjudicación"
                                InputLabelProps={{ shrink: true }}
                            />
                        )}
                    />
            </Grid>
          </Grid>   
        </CHPaper>
    )
} 

type Props = {
    formularioCuadrosAfectados: UseFormReturn<any>;
}

export default CuadrosAfectados;