import React, { useEffect, useState } from 'react';
import { connect } from 'react-redux';
import { Grid, makeStyles, createStyles,Typography, } from '@material-ui/core';
import CHPaper from '../../../components/ch-paper/CHPaper';
import { CatalogState } from '../../../reducers/catalog.reducer';
import { ClienteDto } from '../../../types/client.model.type';
import UtilService from '../../../utils/util.service';


const useStyles = makeStyles(() =>
    createStyles({
        column: {
            padding: '10px',
            textAlign: 'center'
        }, 
        titleform: {
            width: '100%',
            textAlign: 'center',
            color: '#1C3F8B',
            padding: 1,
            fontWeight: 'bold',
            fontSize: '1rem',
        }, 
        titleCampo: {
            fontSize: '10px',
           
        },       
    }),
);

function Embargos({
    clientModel,
    catalogState
}: {
    catalogState: CatalogState;
    clientModel: ClienteDto;
}){ 
    const classes = useStyles(); 
   
        return(
            <CHPaper title="Embargos">
                
                    <Typography className={classes.titleform} variant="h5" component="h6">
                        Embargos
                    </Typography>
                   
                    <table className="table">
                            <thead>
                                <tr>
                                    <th>Radicado</th>
                                    <th>Solicitud</th>                                   
                                    <th>Estado Solicitud</th>
                                    <th>Estado Bloqueo</th>
                                    <th>Código Juzgado</th>
                                    <th>Razón</th>
                                    <th>Monto/Porcentaje</th>
                                </tr>
                            </thead>
                            <tbody>
                                {clientModel?.embargos?.map((element, index) => (
                                    <tr key={`table-schedule${index}`}>
                                        <td className='dateReport3'>{element.radicadoWorkManager}</td>
                                        <td className='dateReport3'>{element.numeroSolicitud}</td>                                        
                                        <td className='dateReport3'>{element.estadoEmbargo}</td>
                                        <td className='dateReport3'>{element.estadoEmbargo!=='EN TRÁMITE'?'ACTIVO':'INACTIVO' }</td>
                                        <td className='dateReport3'>{element.juzgado}</td>
                                        <td className='dateReport3'>{element.tipoProceso}</td>
                                        <td className='dateReport3'>{Number(element.valor)>0&&Number(element.valor)<100?`${element.valor}% `:UtilService.formatCurrency(element.valor)}</td>
                                    </tr>
                                    ))
                                }                                
                            </tbody>
                    </table>
                      
            </CHPaper>   )
    }
   

export default connect()(Embargos);
