import { Button, createStyles, makeStyles } from '@material-ui/core';
import React, { useState } from 'react';
import swal from 'sweetalert';
import { useForm } from 'react-hook-form';
import CHPageTitle from '../../../components/ch-page-title/CHPageTitle';
import CHPrivateContainer from '../../../components/ch-private-container/CHPrivateContainer';
import CuadrosAfectados from './CuadrosAfectados';
import InformacionEntrada from './InformacionEntrada';
import Subsidios from './Subsidios';
import SubsidiosAnulados from './SubsidiosAnulados';
import NotificationService from '../../../services/notification.service';

const useStyles = makeStyles(() =>
    createStyles({
        button: {
            marginTop: '1.5rem',
            marginRight: '.5rem',
        },
        buttonConfirmacion: {
            backgroundColor: '#c4c4c4',
            color: '#595959'
        },
        buttonAnular: {
            backgroundColor: '#c4c4c4',
            color: '#595959'
         },
         buttonCancelar: {
            backgroundColor: '#efefef',
            color: '#595959'
         }
    }),
);

const RealizacionSubsidios = (props: Props) => {

    const classes = useStyles();
    const [subsidiosSeleccionados,setSubsidiosSeleccionados] = useState<any[]>([]);
    const {regresar} = props;

    const formularioInformacionEntrada = useForm({
        defaultValues:{
            numeroResolucion: '',
            fechaInicioResolucion: '',
            fechaCierreResolucion: '',
            estado: '',
            radicado: '',
            totalAdjudicaciones: '',
            montoTotal: ''
        }
    })

    const formularioCuadrosAfectados = useForm({
        defaultValues:{
            totalSubsidios: '',
            totalMonto: '',
            fechaAdjudicacion: '',
        }
    })

    const anular = () => {
        swal({
            title:'¿Es Subsanable?',
            text: '',
            icon: 'warning',
             buttons: {
                 rechazar: {
                   text: 'SI',
                   value: 'SI',
                   className: classes.buttonConfirmacion
                 },
                 anular: {
                     text: 'NO',
                     value: 'NO',
                     className: classes.buttonAnular
                 },
                 cancelar:  {
                     text: 'CANCELAR',
                     value: null,
                     className: classes.buttonCancelar
                 },
             },
             closeOnClickOutside: false,
         })
         .then(respuesta => {
            if (respuesta === 'SI') {
                NotificationService.genericAlert(
                    'Exitoso!',
                    'Se realizó la petición con éxito.',
                );
            }
            else if(respuesta === 'NO'){
                NotificationService.genericAlert(
                    'Exitoso!',
                    'Se realizó la petición con éxito.',
                );
            }
        })
    }

    const generarPdf = () => {
        console.log('generarPdf')
    }

    const cerrarResolucion = () => {
        console.log('cerrarResolucion')
    }

    return(
        <CHPrivateContainer>
            <CHPageTitle
                topText="Gestión de subsidios"
                subText=""
                title1="Realización de"
                title2="Resolución de Subsidios"
            />
            <InformacionEntrada
                formularioInformacionEntrada={formularioInformacionEntrada}
            />
            <CuadrosAfectados
                formularioCuadrosAfectados={formularioCuadrosAfectados}
            />
           <Subsidios
                subsidiosSeleccionados={subsidiosSeleccionados}
                setSubsidiosSeleccionados={setSubsidiosSeleccionados}
                anular={anular}
           />
           <SubsidiosAnulados/>
           <div className="buttons">
                <Button
                    className={classes.button}
                    variant="outlined"
                    color="primary"
                    onClick={generarPdf}
                >
                    GENERAR PDF
                </Button>
                <Button
                    className={classes.button}
                    variant="outlined"
                    color="primary"
                    onClick={cerrarResolucion}
                >
                    CERRAR RESOLUCIÓN
                </Button>
                <Button
                    className={classes.button}
                    variant="outlined"
                    color="primary"
                    onClick={regresar}
                >
                    REGRESAR
                </Button>
            </div>
        </CHPrivateContainer>
    )
}

type Props = {
    regresar: () => void;
}

export default RealizacionSubsidios;