import React, { useEffect, useState } from 'react';
import { Button, createStyles, makeStyles } from '@material-ui/core';
import { BOTONERA_SOLICITUD } from '../../../../constants/constants';
import { ResponseSeveranceModel } from '../../../../models/requests/response-severance.model';

const useStyles = makeStyles(() =>
    createStyles({
        column: {
            padding: '10px',
            textAlign: 'center',
        },
        button: {
            width: '120px',
            marginLeft: '.5rem',
        },
        column2: {
            padding: '10px',
            textAlign: 'left',
        },
        buttonAdd: {
            width: '200px',
            marginLeft: '.5rem',
        },
        columnButtonAdd: {
            textAlign: 'right',
        },
        columnLabel: {
            padding: '10px',
        },
    }),
);

function BotoneraInformacionSolicitudComponent({
    onItemGoBack,
    onSubmit,
    onSubmitAprobar,
    onSubmitSubsanar,
    onSubmitRechazar,
    onSubmitGenerarPago,
    tipoAccion,
    disabledActualizar,
    disabledAprobar,
    disabledSubsanar,
    disabledRechazar,
    disabledRegresar,
    tipoAccionDetalleProcesar,
    responseSolicitud,
    currentTabValue,
    aprobarBloquear,
    hablitarActualiza,
    deshabilitarBTNRechazarGp2,
    deshalitarBotonesInconsistencia,
    userAsig,
	grupo,
	userIngreso

}: {
    onItemGoBack: () => void;
    onSubmit: (value: any) => Promise<void>;
    onSubmitAprobar: () => void;
    onSubmitSubsanar: () => void;
    onSubmitRechazar: () => void;
    onSubmitGenerarPago: any;
    tipoAccion: number;
    disabledActualizar: boolean;
    disabledAprobar: boolean;
    disabledSubsanar: boolean;
    disabledRechazar: boolean;
    disabledRegresar: boolean;
    tipoAccionDetalleProcesar: boolean;
    responseSolicitud: ResponseSeveranceModel | undefined;
    currentTabValue: any;
    aprobarBloquear: any;
    hablitarActualiza: any;
    deshabilitarBTNRechazarGp2: any;
    deshalitarBotonesInconsistencia: boolean;
    userAsig: string | undefined;
	grupo: any;
	userIngreso: string;

}) {
    
    const classes = useStyles();

    const [tipoAccionDetalleProcesarSubsanar, settipoAccionDetalleProcesarSubsanar] = useState<boolean>(false);
    const [actualizarHabilitado, setActualizarHabilitado] = useState<boolean>(false);
    const [aprobarHabilitado, setAprobarHabilitado] = useState<boolean>(false);
    const [actualizacionCompletada, setActualizacionCompletada] = useState<boolean>(false);

    useEffect(() => {

        settipoAccionDetalleProcesarSubsanar(tipoAccionDetalleProcesar);
        if (responseSolicitud?.nombreTarea?.includes('Cargue de documentos') || responseSolicitud?.nombreTarea?.includes('Seguridad documental grupo')) {
            settipoAccionDetalleProcesarSubsanar(true);
        }
    }, []);

    useEffect(() => {
        if (responseSolicitud?.nombreTarea === 'Verificación cuenta individual') {

            setActualizarHabilitado(true);
            setAprobarHabilitado(false);
        }
    }, [responseSolicitud?.nombreTarea]);

    useEffect(() => {
        if (actualizacionCompletada) {
            setAprobarHabilitado(true);
        }
    }, [actualizacionCompletada]);

    const handleActualizar = async (data: any) => {
        try {
            await onSubmit(data);
            setActualizacionCompletada(true);
        } catch (error) {
            console.error("Error en la actualización:", error);
            setActualizacionCompletada(false);
        }
    };

    const renderActionButton = () => {
        const tarea = responseSolicitud?.nombreTarea;
        if (tarea?.includes('Verificación cuenta individual') && currentTabValue === 4) {
            return (
                <Button
                    className={classes.button}
                    variant="outlined"
                    onClick={onSubmitGenerarPago}
                    disabled={tipoAccionDetalleProcesar ? true : disabledAprobar}
                >
                    GENERAR PAGO
                </Button>
            );
        }

        return (
            <Button
                className={classes.button}
                variant="outlined"
                onClick={onSubmitAprobar}
                disabled={tipoAccionDetalleProcesar || deshalitarBotonesInconsistencia  || disabledAprobar}

                // no delete
                // disabled={tipoAccionDetalleProcesar || deshalitarBotonesInconsistencia || !aprobarHabilitado}
                // disabled={tipoAccionDetalleProcesar || deshalitarBotonesInconsistencia  || disabledAprobar || !aprobarHabilitado}
            >
                APROBAR
            </Button>
        );
        
        return null;

    };

    const renderActionButtonRechazar = () => {

        if (!responseSolicitud?.nombreTarea?.includes("Seguridad documental grupo 1") && !responseSolicitud?.nombreTarea?.includes("Seguridad documental grupo 2") && !responseSolicitud?.nombreTarea?.includes('Verificación cuenta individual')) {
            return (
                <Button
                    className={classes.button}
                    variant="outlined"
                    onClick={onSubmitRechazar}
                  //  disabled={tipoAccionDetalleProcesar ? true : disabledRechazar || deshalitarBotonesInconsistencia}
                    disabled={userAsig !== userIngreso || tipoAccionDetalleProcesar ? true : disabledRechazar || deshalitarBotonesInconsistencia}
                >
                    RECHAZAR
                </Button>
            )

        }
        if (responseSolicitud?.nombreTarea?.includes("Seguridad documental grupo 2")) {
            return (

                <Button
                    className={classes.button}
                    variant="outlined"
                    onClick={onSubmitRechazar}
                   // disabled={tipoAccionDetalleProcesar ? true : disabledRechazar || deshabilitarBTNRechazarGp2}
                    disabled={userAsig !== userIngreso || tipoAccionDetalleProcesar ? true : disabledRechazar || deshabilitarBTNRechazarGp2}
                >
                    RECHAZAR
                </Button>


            )
        }

        if (responseSolicitud?.nombreTarea?.includes("Verificación")) {
            return (

                <Button
                    className={classes.button}
                    variant="outlined"
                    onClick={onSubmitRechazar}
                    // disabled={tipoAccionDetalleProcesar ? true : disabledRechazar || deshabilitarBTNRechazarGp2}
                    disabled={userAsig !== userIngreso || tipoAccionDetalleProcesar ? true : disabledRechazar || deshabilitarBTNRechazarGp2}
                >
                    RECHAZAR
                </Button>


            )
        }
        return null;
    }

    return tipoAccion === BOTONERA_SOLICITUD.ACTUALIZAR ? (
        <>
            <div className="buttons">
                {
                    responseSolicitud?.nombreTarea?.includes('Seguridad documental grupo') ?
                        <Button
                            className={classes.button}
                            variant="outlined"
                            onClick={onSubmit}
                            disabled={userAsig !== userIngreso || tipoAccionDetalleProcesar ? true : disabledRechazar || hablitarActualiza}
                           // disabled={tipoAccionDetalleProcesar ? true : disabledRechazar || hablitarActualiza}
                        >
                            ACTUALIZAR

                        </Button> :
                        <Button
                            className={classes.button}
                            variant="outlined"
                            onClick={handleActualizar}
                            // disabled={tipoAccionDetalleProcesar ? true : disabledActualizar || deshalitarBotonesInconsistencia}
                            disabled={userAsig !== userIngreso || tipoAccionDetalleProcesar ? true : disabledActualizar || deshalitarBotonesInconsistencia}
                        >
                            ACTUALIZAR
                        </Button>
                }


                {renderActionButton()}

                {renderActionButtonRechazar()}

                        <Button
                            className={classes.button}
                            variant="outlined"
                            onClick={onSubmitSubsanar}
                            disabled={userAsig !== userIngreso || tipoAccionDetalleProcesarSubsanar ? true : disabledSubsanar}
                           // disabled={tipoAccionDetalleProcesarSubsanar ? true : disabledSubsanar}
                        >
                            SUBSANAR
                        </Button> 
                       
                <Button
                    className={classes.button}
                    variant="outlined"
                    onClick={onItemGoBack}
                    disabled={disabledRegresar}
                >
                    REGRESAR
                </Button>
            </div>
        </>
    ) : null;
}

export default BotoneraInformacionSolicitudComponent;

