import { Button, createStyles, Grid, makeStyles } from '@material-ui/core';
import React from 'react';
import CHPaper from '../../../components/ch-paper/CHPaper';

const useStyles = makeStyles(() =>
    createStyles({
        checkBox: {
            backgroundColor: '#0075ff',
            accentColor: '#1c3f8b',
            marginTop: '6px',
            width:'18px',
            height: '18px',
            cursor: 'pointer',
        },
        columnButtonAnular: {
            textAlign: 'right',
        },
        buttonAnular: {
            width: '275px',
            marginLeft: '.5rem',
        },
    }),
);

const Subsidios = (props: Props) => {
    const classes = useStyles();
    const {subsidiosSeleccionados, setSubsidiosSeleccionados, anular} = props;
    return(
        <CHPaper title="Subsidios">
                <table className="credit-table"    
                    style={{
                        margin: '10px',
                        width: '99%',
                    }}>
                    <thead>
                    <tr>
                        <th style={{ textAlign: 'center'}}>
                            <input type="checkbox" className={classes.checkBox} />
                        </th>
                        <th style={{ textAlign: 'center' }}>
                           Documento
                        </th>
                        <th style={{ textAlign: 'center' }}>
                           Radicado
                        </th>
                        <th style={{ textAlign: 'center', width: '20%' }}>
                           Afiliado
                        </th>
                        <th style={{ textAlign: 'center' }}>
                           CDP
                        </th>
                        <th style={{ textAlign: 'center', width: '20%' }}>
                           Tercero
                        </th>
                        <th style={{ textAlign: 'center' }}>
                           Factura
                        </th>
                        <th style={{ textAlign: 'center' }}>
                           Monto
                        </th>
                        <th style={{ textAlign: 'center', width: '8%' }}>
                           Estado Solicitud
                        </th>
                    </tr>
                </thead>
                <tbody>
                        <tr style={{ textAlign: 'center'}}>
                            <td><input type="checkbox" className={classes.checkBox} /></td>
                            <td> </td>
                            <td> </td>
                            <td> </td>
                            <td> </td>
                            <td> </td>
                            <td> </td>
                            <td> </td>
                            <td> </td>
                        </tr>
                </tbody>
              </table> 
           <Grid className={classes.columnButtonAnular} item xs={12} md={12}>
                <Button
                    className={classes.buttonAnular}
                    variant="outlined"
                    style={{ marginRight: '5px' }}
                    onClick={anular}
                >
                    ANULAR
                </Button>
           </Grid>
        </CHPaper>
    )
}

type Props = {
    subsidiosSeleccionados: any[];
    setSubsidiosSeleccionados: (subsidios: any[]) => void;
    anular: () => void;
}

export default Subsidios;