import React, { useEffect, useState } from 'react';
import { Button, createStyles, Grid, makeStyles, } from '@material-ui/core';
import { connect } from 'react-redux';
import { toast } from 'react-toastify';
import CHPaperNew from '../../../components/ch-paper-new/CHPaperNew';
import ApiReportes from '../../../services/api-reportes.service';
import { startGetTramiteEntity } from '../../../actions/educationalEntities.actions';
import ApiEntidadesEducativas from '../../../services/api-entidadesEducativas.service';
import { TramiteEntity } from '../../../types/educational.entities.type';
import ApiClients from '../../../services/api-clients.service';
import ApiCatalogo from '../../../services/api-catalog.service';
import { IDENTIFICATIONTYPEDTO } from '../../../types/catalog.type';
import AuthService from '../../../services/auth.service';
import { Auditoria } from '../../../types/Auditoria.model.type';
import AuditoriaApi from '../../../services/api-auditorias.servise';

const useStyles = makeStyles(() =>
    createStyles({

        icon: {
            padding: '8px',
            textAlign: 'inherit',
            color: '#42b7ef',
            margin: '10px'
        },

        iconRed: {
            padding: '8px',
            textAlign: 'inherit',
            color: '#FF0000',
            margin: '10px'
        },

        button: {
            backgroundColor: '#1C3F8B',
            color: '#fff',
            width: '18%',
            marginLeft: '80%',
        },

    }),
);
function procedureHistoryEntity({
    idEntity,
}: {
    idEntity: any;
}): any {
    const classes = useStyles();
    const apiClientes = ApiClients();
    const apiCatalogo = ApiCatalogo();
    const apiEntidadesEducativas = ApiEntidadesEducativas();
    const [dataTramites, setDataTramites] = useState<any[]>([]);
    const [tiposIdentificacion, setTiposIdentificacion] = useState<IDENTIFICATIONTYPEDTO[]>([]);

    useEffect(() => {
        if(idEntity){
            obtenerTiposIdentificacion();
            consultarListaTramites(idEntity);
        }
    }, [idEntity]);

    const obtenerTiposIdentificacion = async() => {
        await apiCatalogo.getAllTypeDocuments()
            .then(response => {
                if(response.data){
                    setTiposIdentificacion(response.data);
                }
            }).catch((error)=> {
                toast(`Error al consultar tipos de documentos en tramites: ${error}`,{ type: toast.TYPE.ERROR });
            })
    }

    const [publicIpAddress, setPublicIpAddress] = useState<string | null>(null);
    const [localIpAddress, setLocalIpAddress] = useState<string | null>(null);
    const catalogApi = ApiCatalogo();

    const isValidIPv4 = (ip: string) => {
        const ipv4Regex = /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
        return ipv4Regex.test(ip);
    };

    const isValidIPv6 = (ip: string) => {
        const ipv6Regex = /([a-f0-9:]+:+)+[a-f0-9]+/i;
        return ipv6Regex.test(ip);
    };

    const enviarIp = async (ip: any) => {
        const convertIp = ip.split('.')[0]

        const hexadecimal = convertIp
        await catalogApi
            .getObtenerIpLocal(hexadecimal)
            .then(async (response: any) => {

                if (response) {
                    if (response.isSuccess) {
                        setPublicIpAddress(response.data);
                    }
                }
            })
            .catch(e => {
                toast('Error del sistema', { type: toast.TYPE.ERROR });
            });

    }

    useEffect(() => {
        const fetchLocalIPAddress = () => {
            const peerConnection = new RTCPeerConnection({ iceServers: [] });
            peerConnection.createDataChannel('');
            peerConnection.createOffer()
                .then((offer) => peerConnection.setLocalDescription(offer))
                .catch((error) => console.error('Error creating offer:', error));

            peerConnection.onicecandidate = (event) => {
                if (event.candidate) {
                    const ip: any = event.candidate.address;
                    if (isValidIPv4(ip) || isValidIPv6(ip)) {
                        setLocalIpAddress(ip);
                        enviarIp(ip);
                    } else {
                        setLocalIpAddress(ip);
                        enviarIp(ip);
                    }
                }
            };

            return () => {
                peerConnection.close();
            };
        };
        fetchLocalIPAddress();

    }, []);
   
    const onClickExcel = async () => {
        const columnDataList = dataTramites?.map((row:any) => ({
            data: [
                mostrarDescripcionIdentificacion(row.tipoDocumento),
                String(row.cedula),
                row.nombre || '',
                String(row.radicado) || '',
                row.tipoSolicitud,
                row.tipoSolicitud || '',
                row.fechaCreacion ? (
                    new Date(row.fechaCreacion).toLocaleDateString('es-ES') || ' ' ||
                    new Date(row.fechaCreacion).toLocaleTimeString('en-US', {
                        hour: 'numeric',
                        minute: 'numeric',
                        hour12: true
                    })
                ) : 'No disponible',

                row.programa || '',
                row.nivel || '',
                row.estado || ''
            ]
        }));

        if (columnDataList) {
            const request = {
                columnDataList: columnDataList.map(item => ({
                    data: item.data
                })),
                columnName: [
                    "Tipo de Documento",
                    "N° Documento Afiliado",
                    "Nombres/Razón Social",
                    "N° Radicado",
                    "Tipo Solicitud",
                    "Modalidad",
                    "Fecha Solicitud",
                    "Programa Educativo",
                    "Nivel Educativo",
                    "Estado"
                ]
            };

            const apiReportes = ApiReportes();
            const response = await apiReportes.GenerarExcels(request);
            const blob = new Blob([response], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
            const url = window.URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = 'archivo.xlsx';
            document.body.appendChild(link);
            link.click();

            window.URL.revokeObjectURL(url);

            const auditoriaApi = AuditoriaApi();
            const user = AuthService.getUserInfo();
            const nav = window.navigator as any;
            const usrAg = nav.userAgentData.brands.find(
                (x: { brand: string }) => x.brand === 'Google Chrome' || x.brand === 'Microsoft Edge'
            )?.brand;
    
            const requestAuditoria = {
                navegador: usrAg,
                sistemaOperativo: nav.userAgentData.platform,
                nombreUsuario: user.USR_USERNAME,
                usurioId: user.USR_ID,
                ip: publicIpAddress,
                modulo: 'Gestión de entidades',
                hostname: document.location.host,
                tipoAccion: 'DESCARGAS',
                idTipoAccion: 5,
                descripcion: 'Descarga de reporte Lista de tramites'
    
            } as Auditoria;
    
            auditoriaApi.InsertAuditoria(requestAuditoria);
        }
    };

    const consultarListaTramites = async(idEntidad: string) => {
        try{
            const response = await apiEntidadesEducativas.startGetTramiteEntity(idEntidad);
            if(response?.data && response?.data.length > 0){

                const tramites: any[] = [];
                await Promise.all(response?.data.map(async (item: any) => {
                    if(item){
                        await apiClientes.postObtenerInformacionClienteCedula(Number(item?.cedula))
                        .then(responseCliente => {
                            if(responseCliente.data){
                                const tramite = {
                                    tipoDocumento: responseCliente.data?.idTipoIdentificacion,
                                    cedula: item?.cedula,
                                    nombre: `${responseCliente.data?.primerNombre} ${responseCliente.data?.segundoNombre || ''} ${responseCliente.data?.primerApellido} ${responseCliente.data?.segundoApellido || ''}`,
                                    radicado: item?.radicado,
                                    tipoSolicitud: item?.modalidad,
                                    tipoModalidad: item?.subModalidad,
                                    fechaCreacion: item?.fechaCreacion,
                                    programa: item?.programa,
                                    nivel: item?.nivel,
                                    estado: item?.estado
                                }
                                tramites.push(tramite);
                            }
                        })
                        .catch((error) => {
                            toast(`Error al consultar información del afiliado en tramites:${error}`,{ type: toast.TYPE.ERROR });
                            setDataTramites([]);
                        });
                    }
                }))
                setDataTramites(tramites);

                // Mensajes solicitudes Procesadas
                if(response?.data.length >= 2){
                    const solicitudesProcesadas = response?.data.filter((solicitud:any) => solicitud?.estado === 'PROCESADA');
                    if(solicitudesProcesadas && solicitudesProcesadas.length >= 2){
                          toast('La entidad registra dos o más pagos',{ type: toast.TYPE.ERROR });
                    }else if (solicitudesProcesadas && solicitudesProcesadas.length === 1) {
                          toast('La entidad registra un pago',{ type: toast.TYPE.ERROR });
                    }else if(solicitudesProcesadas && solicitudesProcesadas.length === 0){
                          toast('La entidad no registra pagos',{ type: toast.TYPE.ERROR });
                    }
                }
            }
           
        }catch (error) {
            toast(`Error al obtener datos de la entidad:${error}`,{ type: toast.TYPE.ERROR });
            setDataTramites([]);
        }
    }

    const mostrarDescripcionIdentificacion = (idTipoIdentificacion: number) => {
        const identificacion = tiposIdentificacion?.find((item:IDENTIFICATIONTYPEDTO) => item?.id === idTipoIdentificacion);
        return identificacion?.descripcion
    }

    return (
        <Grid container>
            <CHPaperNew>
                <table className="table">
                    <thead>
                        <tr>
                            <th className='column2'>Tipo de Documento</th>
                            <th className='column2'>N° Documento Afiliado</th>
                            <th className='column2'>Nombres/Razón Social</th>
                            <th className='column2'>N° Radicado</th>
                            <th className='column2'>Tipo Solicitud</th>
                            <th className='column2'>Modalidad</th>
                            <th className='column2'>Fecha Solicitud</th>
                            <th className='column2'>Programa Educativo</th>
                            <th className='column2'>Nivel Educativo</th>
                            <th className='column2'>Estado</th>
                        </tr>
                    </thead>
                    <tbody>
                        {dataTramites && dataTramites.length > 0 && dataTramites.map((row: any, index: number) => (
                            <tr key={`table-${index}`}>
                                <td className='tab-space-01'>{mostrarDescripcionIdentificacion(row.tipoDocumento)}</td>
                                <td className='tab-space-01'>{row.cedula}</td>
                                <td className='tab-space-01'>{row.nombre}</td>
                                <td className='tab-space-01'>{row.radicado}</td>
                                <td className='tab-space-01'>{row.tipoSolicitud}</td>
                                <td className='tab-space-01'>{row.tipoSolicitud}</td>
                                <td className='tab-space-01'>
                                    {new Date(row.fechaCreacion).toLocaleDateString('es-ES')} {' '}
                                    {new Date(row.fechaCreacion).toLocaleTimeString('en-US', {
                                        hour: 'numeric',
                                        minute: 'numeric',
                                        hour12: true
                                    })}
                                </td>
                                <td className='tab-space-01'>{row.programa}</td>
                                <td className='tab-space-01'>{row.nivel}</td>
                                <td className='tab-space-01'>{row.estado}</td>
                            </tr>
                        ))}
                        {dataTramites && dataTramites.length === 0 && (
                            <tr>
                                <td colSpan={9} style={{ textAlign: 'center' }}>No hay datos disponibles</td>
                            </tr>
                        )}
                    </tbody>
                </table>
                <div className="buttons">
                    <Button
                        className={classes.button}
                        variant="outlined"
                        type="submit"
                        onClick={() => onClickExcel()}
                    >
                        REPORTE
                    </Button>
                </div>

            </CHPaperNew>
        </Grid>
    );
}

const mapDispatchToProps = (dispatch: any) => ({
    obtenerTramite: (idEntidad: string) =>
        dispatch(startGetTramiteEntity(idEntidad))
});

export default connect(null, mapDispatchToProps)(procedureHistoryEntity);
