import { Button, Grid } from '@material-ui/core';
import { createStyles, makeStyles, Theme } from '@material-ui/core/styles';
import React, { useEffect, useState } from 'react';
import { Controller, useForm } from 'react-hook-form';
import { toast } from 'react-toastify';
import afiliadoApi from '../../services/api-afiliado.service';
import CreditApi from '../../services/api-credit.service';

import NotificationService from '../../services/notification.service';
import CHDatePicker from '../ch-datepicker/CHDatepicker';
import CHPaper from '../ch-paper/CHPaper';
import CHTextField from '../ch-text-field/CHTextField';

const useStyles = makeStyles(() =>
    createStyles({
        column: {
            padding: '10px',
            textAlign: 'center',
        },
        button: {
            width: '120px',
            marginLeft: '.5rem',
        },
        column2: {
            padding: '10px',
            textAlign: 'left',
        },
    }),
);
function DatosAliadosEstrategicos(procedureRequest: any) {
    const apiEstrategico = afiliadoApi()
    const  creditApi = CreditApi()
    const formularioDatosAliadosEstrategicos = useForm({
        defaultValues: {
            nombreAliadoEstrategico: '',
            fechaPagoEstudioTitulos: new Date(),
            FechaRecepcionEstudioTtitulos: new Date(),
            concepto: '',
            tipoParqueadero: '',
            percentageExtraBonus: 0,
            talla: 0,
            peso: 0
        },
    })

    useEffect(() => {
        obtenerDatosAliadosEstrategicos();
        obtenerPesoYTalla();
    }, [])

    const [ObtenerAliadoActilizar, setObtenerAliadoActilizar] = useState(0)


    const obtenerPesoYTalla = async () => {
            const request = procedureRequest?.procedureRequest?.requestID;
        await creditApi
            .postObtenerPesoYTalla(request)
            .then(async (response: any) => {
                if (response) {
                    if (response.isSuccess) {
                        if (response.data === null) {
                            return
                        }
                        const aliados = response.data
                        formularioDatosAliadosEstrategicos.setValue('peso', aliados?.soC_PESO)
                        formularioDatosAliadosEstrategicos.setValue('talla', aliados?.soC_TALLA)
                    }
                }
            })
            .catch(e => {
                toast('Error del sistema', { type: toast.TYPE.ERROR });
            });
    }

    const obtenerDatosAliadosEstrategicos = async () => {
        const response = {
            soc_Id: procedureRequest?.procedureRequest?.requestID,
        }
        await apiEstrategico
            .postObtenerAliadosEstrategicos(response)
            .then(async (response: any) => {

                if (response) {
                    if (response.isSuccess) {
                        if (response.data === null) {
                            return
                        }

                        const aliados = response.data
                        setObtenerAliadoActilizar(aliados.dat_Id)
                        formularioDatosAliadosEstrategicos.setValue('nombreAliadoEstrategico', aliados.nombre_Aliado)
                        formularioDatosAliadosEstrategicos.setValue('fechaPagoEstudioTitulos', aliados.fecha_Pago_Estudio_Titulo)
                        formularioDatosAliadosEstrategicos.setValue('FechaRecepcionEstudioTtitulos', aliados.fecha_Recepcion_Estudio_Titulo)
                        formularioDatosAliadosEstrategicos.setValue('concepto', aliados.concepto)
                        formularioDatosAliadosEstrategicos.setValue('tipoParqueadero', aliados.tipo_Parqueadero)
                        formularioDatosAliadosEstrategicos.setValue('percentageExtraBonus', aliados.percentageExtraBonus)
                        // formularioDatosAliadosEstrategicos.setValue('peso', aliados.peso)
                        // formularioDatosAliadosEstrategicos.setValue('talla', aliados.talla)
                    }
                }
            })
            .catch(e => {
                toast('Error del sistema', { type: toast.TYPE.ERROR });
            });

    }



    const agregarEstratigico = async (data: any) => {

        const response = {
            dat_Id: 0,
            soc_Id: procedureRequest?.procedureRequest?.requestID,
            nombre_Aliado: data.nombreAliadoEstrategico,
            fecha_Pago_Estudio_Titulo: data.fechaPagoEstudioTitulos,
            fecha_Recepcion_Estudio_Titulo: data.FechaRecepcionEstudioTtitulos,
            concepto: data.concepto,
            tipo_Parqueadero: data.tipoParqueadero,
            percentageExtraBonus: Number(data.percentageExtraBonus),
        }


        await apiEstrategico
            .postAliadosEstrategicos(response)
            .then(async (response: any) => {
                if (response) {
                    if (response.isSuccess) {
                        setObtenerAliadoActilizar(response.data.dat_Id)
                        await NotificationService.genericAlert(
                            'Guardado',
                            'guardado con exito.',

                        );
                    }
                }
            })
            .catch(() => {
                toast('Error del sistema', { type: toast.TYPE.ERROR });
            });



    }

    const actulizarDatosEstrategicos = async (data: any) => {
        const response = {
            dat_Id: ObtenerAliadoActilizar,
            soc_Id: procedureRequest?.procedureRequest?.requestID,
            nombre_Aliado: data.nombreAliadoEstrategico,
            fecha_Pago_Estudio_Titulo: data.fechaPagoEstudioTitulos,
            fecha_Recepcion_Estudio_Titulo: data.FechaRecepcionEstudioTtitulos,
            concepto: data.concepto,
            tipo_Parqueadero: data.tipoParqueadero,
            percentageExtraBonus: Number(data.percentageExtraBonus),
        }

        await apiEstrategico
            .postActulaizarAliadoEstrategico(response)
            .then(async (response: any) => {
                if (response) {
                    if (response.isSuccess) {
                        await NotificationService.genericAlert(
                            'Actualizado',
                            'guardado con éxito.',

                        );
                    }
                }
            })
            .catch(() => {
                toast('Error del sistema', { type: toast.TYPE.ERROR });
            });
    }


    const classes = useStyles();
    return (
        <>
            <CHPaper title="Datos Aliados Estratégicos">
                <Grid container>
                    <Grid className={classes.column} item xs={12} md={3}>
                        <Controller
                            name="nombreAliadoEstrategico"
                            control={formularioDatosAliadosEstrategicos.control}

                            render={({
                                field: { onChange, value },
                                fieldState: { error },
                            }) => (
                                <CHTextField
                                    label="Nombre Aliado Estratégico "
                                    value={value}
                                    onChange={onChange}
                                />
                            )}
                        />


                    </Grid>
                    <Grid className={classes.column} item xs={12} md={3}>
                        <Controller
                            name="fechaPagoEstudioTitulos"
                            rules={{
                                required: 'Este campo es requerido',

                            }}
                            control={formularioDatosAliadosEstrategicos.control}
                            render={({
                                field: { onChange, value },

                            }) => (
                                <CHDatePicker
                                    label="Fecha de Pago Estudio Títulos "
                                    inputProps={{ readOnly: true }}
                                    onChange={onChange}
                                    value={value}

                                    autoOk
                                />
                            )}
                        />
                    </Grid>
                    <Grid className={classes.column} item xs={12} md={3}>
                        <Controller
                            name="FechaRecepcionEstudioTtitulos"

                            control={formularioDatosAliadosEstrategicos.control}
                            render={({
                                field: { onChange, value },
                                fieldState: { error },
                            }) => (
                                <CHDatePicker
                                    label="Fecha Recepcion Estudio Títulos "
                                    inputProps={{ readOnly: true }}
                                    onChange={onChange}
                                    value={value}

                                    autoOk
                                />
                            )}
                        />
                    </Grid>
                    <Grid className={classes.column} item xs={12} md={3}>
                        <Controller
                            name="concepto"
                            control={formularioDatosAliadosEstrategicos.control}

                            render={({
                                field: { onChange, value },
                                fieldState: { error },
                            }) => (
                                <CHTextField
                                    label="Concepto "
                                    value={value}
                                    onChange={onChange}
                                />
                            )}
                        />


                    </Grid>

                    <Grid item md={4} className={classes.column}>
                        <Controller
                            name="percentageExtraBonus"
                            control={formularioDatosAliadosEstrategicos.control}
                            rules={{
                                required: 'Este campo es requerido.',
                                pattern: {
                                    value: /^\d*\.?\d*$/,
                                    message:
                                        'Solo se aceptan caracteres numericos',
                                },
                                min: {
                                    value: 0,
                                    message:
                                        'El valor a ingresar es de 0 a 100',
                                },
                                max: {
                                    value: 100,
                                    message:
                                        'El valor no puede ser mayor a 100',
                                },
                            }}
                            render={({
                                field: { onChange, value },
                                fieldState: { error },
                            }) => (
                                <CHTextField
                                    error={!!error}
                                    helperText={error ? error.message : null}
                                    isReadOnly={
                                        procedureRequest.stateActivityID === 4
                                    }
                                    label="Porcentaje Extraprima(%) *"
                                    value={value}
                                    inputProps={{
                                        style: {
                                            textAlign: 'right',
                                        },
                                    }}
                                    onChange={e => {
                                        if (e.target.value.length <= 3) {
                                            onChange(
                                                e.target.value.replace(
                                                    /[a-zA-ZñÑáéíóúÁÉÍÓÚ/@=+:{}#%$()*&¡!¿?[|`"~,<>^_-]/g,
                                                    '',
                                                ),
                                            );
                                        }
                                    }}
                                />
                            )}
                        />
                    </Grid>
                   
                    {

                        procedureRequest?.procedureRequest?.activity === "ANÁLISIS JURÍDICO CH" ?
                            <>
                                <Grid item md={4} className={classes.column}>
                                    <Controller
                                        name="peso"
                                        control={formularioDatosAliadosEstrategicos.control}
                                        rules={{
                                            required: 'Este campo es requerido.',
                                            pattern: {
                                                value: /^\d*\.?\d*$/,
                                                message:
                                                    'Solo se aceptan caracteres numericos',
                                            },
                                            min: {
                                                value: 0,
                                                message:
                                                    'El valor a ingresar es de 0 a 999',
                                            },
                                            max: {
                                                value: 999,
                                                message:
                                                    'El valor no puede ser mayor a 999',
                                            },
                                        }}
                                        render={({
                                            field: { onChange, value },
                                            fieldState: { error },
                                        }) => (
                                            <CHTextField
                                                error={!!error}
                                                helperText={error ? error.message : null}
                                                
                                                label="Peso (kg)*"
                                                value={value}
                                                inputProps={{
                                                    style: {
                                                        textAlign: 'right',
                                                    },
                                                }}
                                                onChange={e => {
                                                    if (e.target.value.length <= 3) {
                                                        onChange(
                                                            e.target.value.replace(
                                                                /[a-zA-ZñÑáéíóúÁÉÍÓÚ/@=+:{}#%$()*&¡!¿?[|`"~,<>^_-]/g,
                                                                '',
                                                            ),
                                                        );
                                                    }
                                                }}
                                            />
                                        )}
                                    />
                                </Grid>
                                <Grid item md={4} className={classes.column}>
                                    <Controller
                                        name="talla"
                                        control={formularioDatosAliadosEstrategicos.control}
                                        rules={{
                                            required: 'Este campo es requerido.',
                                            pattern: {
                                                value: /^\d*\.?\d*$/,
                                                message:
                                                    'Solo se aceptan caracteres numericos',
                                            },
                                            min: {
                                                value: 0,
                                                message:
                                                    'El valor a ingresar es de 0 a 999',
                                            },
                                            max: {
                                                value: 999,
                                                message:
                                                    'El valor no puede ser mayor a 999',
                                            },
                                        }}
                                        render={({
                                            field: { onChange, value },
                                            fieldState: { error },
                                        }) => (
                                            <CHTextField
                                                error={!!error}
                                                helperText={error ? error.message : null}
                                                
                                                label="Estatura (cm)*"
                                                value={value}
                                                inputProps={{
                                                    style: {
                                                        textAlign: 'right',
                                                    },
                                                }}
                                                onChange={e => {
                                                    if (e.target.value.length <= 3) {
                                                        onChange(
                                                            e.target.value.replace(
                                                                /[a-zA-ZñÑáéíóúÁÉÍÓÚ/@=+:{}#%$()*&¡!¿?[|`"~,<>^_-]/g,
                                                                '',
                                                            ),
                                                        );
                                                    }
                                                }}
                                            />
                                        )}
                                    />
                                </Grid>
                            </> : null
                    }


                    {/* <Grid className={classes.column} item xs={12} md={3}>
                        <Controller
                            name="tipoParqueadero"
                            control={formularioDatosAliadosEstrategicos.control}
                          
                            render={({
                                field: { onChange, value },
                                fieldState: { error },
                            }) => (
                                <CHTextField
                                    label="Tipo de Parqueadero "
                                    value={value}
                                    onChange={onChange}
                                />
                            )}
                        />


                    </Grid> */}
                </Grid>
                {
                    ObtenerAliadoActilizar !== 0 ?
                        <Grid item xs={12} md={3}>
                            <Button
                                variant="contained"
                                type="submit"
                                style={{ backgroundColor: '#1C3F8B', color: 'white' }}
                                onClick={formularioDatosAliadosEstrategicos.handleSubmit(actulizarDatosEstrategicos)}
                            >

                                Actualizar
                            </Button>
                        </Grid> :
                        <Grid item xs={12} md={3}>
                            <Button
                                variant="contained"
                                type="submit"
                                style={{ backgroundColor: '#1C3F8B', color: 'white' }}
                                onClick={formularioDatosAliadosEstrategicos.handleSubmit(agregarEstratigico)}
                            >

                                Guardar
                            </Button>
                        </Grid>
                }

            </CHPaper>
        </>
    )

}

export default DatosAliadosEstrategicos