import React, { useState, useEffect } from 'react';
import { Controller } from 'react-hook-form';
import { makeStyles, createStyles, Grid, Button, Typography } from '@material-ui/core';
import CHPaper from '../../../../components/ch-paper/CHPaper';
import CHTextField from '../../../../components/ch-text-field/CHTextField';
import CHLoadingProcess from '../../../../components/ch-loading-process/CHLoadingProcess';

const useStyles = makeStyles(() =>
  createStyles({
    column: {
      padding: '10px',
      textAlign: 'center',
    },
    titleform: {
      width: '100%',
      textAlign: 'left',
      color: '#1C3F6B',
      padding: 1,
      fontWeight: 'bold',
      fontSize: '1rem',
      marginLeft: '10px'
    },
  }),
);


const TABS_INDEX = {
  RESUMENSOLICITUD: 'resumen',
  CARGUEDOCUMENTOS: '0',
  CARGUEDOCUMENTOSEGURIDADOCUMENTAL: '1',
  CARGUERETIROPARCIAL: 'carguededocumentosretiroparcial',
  CARGUEDOCUMENTOSV14: 'carguededocumentosv14',
  CARGUEDOCUMENTOSV8: 'carguededocumentosv8',
  INCONSISTENCIAS: '4',
  SEGURIDADDOCUMENTAL: '8',
  VERDETALLESOLICITUD: 'Detalle Solicitud',
  VERDETALLESOLICITUDVERIFICACION: '9',
  VERIFICACIONCUENTAINDIVIDUAL: '10',
  VERIFICACIONESDECUENTA: '11',
  TRAMITEDEPAGO: '12',
}

const ObservacionesSolicitud = ({
  control,
  seccion,
  trazabilidad,
}: {
  control: any;
  seccion: string;
  trazabilidad: any[];
}) => {

  const classes = useStyles();
  const [mostrarObservacionSoloLectura, setMostrarObservacionSoloLectura] = useState(false);
  const [mostrarObservacionGrupo2, setMostrarObservacionGrupo2] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    validaciones();
  }, [seccion]);  

  const validaciones = () => {
    setLoading(true);
    let actividad;

    if(seccion && (seccion === TABS_INDEX.VERDETALLESOLICITUD) &&
       trazabilidad?.some((item: any, index: number) => item?.descripcionEstadoSolicitud === 'RECHAZADA' && index === 1)){
        actividad = trazabilidad?.find((item: any, index: number) => String(item?.descripcionTarea).includes('Radicación') && index === 0);
        control.setValue('observaciones', actividad?.observacion);
        setMostrarObservacionSoloLectura(false);
        setMostrarObservacionGrupo2(false);
        setLoading(false);
    }
    else if (seccion && (seccion === TABS_INDEX.VERDETALLESOLICITUD) &&
        trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación en tiempo') && (item?.descripcionEstadoSolicitud === 'EN TRÁMITE' || item?.descripcionEstadoSolicitud === 'PENDIENTE'))) {

        actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Verificación en tiempo') && (item?.descripcionEstadoSolicitud === 'EN TRÁMITE' || item?.descripcionEstadoSolicitud === 'PENDIENTE'));
        control.setValue('observaciones', actividad?.observacion);
        setMostrarObservacionSoloLectura(false);
        setMostrarObservacionGrupo2(false);
        setLoading(false);
    }
    else if (seccion && (seccion === TABS_INDEX.VERDETALLESOLICITUD) &&
        trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Radicación') && item?.descripcionEstadoSolicitud === 'EN TRÁMITE')) {

        actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Radicación') && item?.descripcionEstadoSolicitud === 'EN TRÁMITE');
        control.setValue('observaciones', actividad?.observacion);
        setMostrarObservacionSoloLectura(false);
        setMostrarObservacionGrupo2(false);
        setLoading(false);
    }
    else if (seccion && (seccion === TABS_INDEX.VERDETALLESOLICITUD) &&
      trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Radicación') && item?.descripcionEstadoSolicitud === 'APROBADA') &&
      trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Radicación') && item?.descripcionEstadoSolicitud === 'PENDIENTE')) {

      actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Radicación') && item?.descripcionEstadoSolicitud === 'APROBADA');
      control.setValue('observaciones', actividad?.observacion);
      setMostrarObservacionSoloLectura(false);
      setMostrarObservacionGrupo2(false);
      setLoading(false);
    }
    else if (seccion && (seccion === TABS_INDEX.VERDETALLESOLICITUD || seccion === TABS_INDEX.VERDETALLESOLICITUDVERIFICACION) &&
      trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Radicación') && item?.descripcionEstadoSolicitud === 'APROBADA') &&
      !trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Radicación') && item?.descripcionEstadoSolicitud === 'PENDIENTE')) {

      actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Radicación') && item?.descripcionEstadoSolicitud === 'APROBADA');
      control.setValue('observaciones', actividad?.observacion);
      setMostrarObservacionSoloLectura(true);
      setMostrarObservacionGrupo2(false);
      setLoading(false);
    }
    else if (seccion && (seccion === TABS_INDEX.CARGUEDOCUMENTOSV14 || seccion === TABS_INDEX.CARGUEDOCUMENTOSV8 || seccion === TABS_INDEX.CARGUEDOCUMENTOS || seccion === TABS_INDEX.CARGUEDOCUMENTOSEGURIDADOCUMENTAL || seccion === TABS_INDEX.CARGUERETIROPARCIAL)
      && trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Cargue de documentos') && (item?.descripcionEstadoSolicitud === 'PENDIENTE' || item?.descripcionEstadoSolicitud === 'INCONSISTENTE'))) {

      actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Cargue de documentos') && (item?.descripcionEstadoSolicitud === 'PENDIENTE' || item?.descripcionEstadoSolicitud === 'INCONSISTENTE'));
      control.setValue('observaciones', String(actividad?.observacion === null ? '' : actividad?.observacion));
      setMostrarObservacionGrupo2(false);
      setLoading(false);
    }
    else if (seccion && (seccion === TABS_INDEX.CARGUEDOCUMENTOSV14 || seccion === TABS_INDEX.CARGUEDOCUMENTOSV8 || seccion === TABS_INDEX.CARGUEDOCUMENTOS || seccion === TABS_INDEX.CARGUEDOCUMENTOSEGURIDADOCUMENTAL || seccion === TABS_INDEX.CARGUERETIROPARCIAL)
      && trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Cargue de documentos') && item?.descripcionEstadoSolicitud === 'APROBADA')) {

      actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Cargue de documentos') && item?.descripcionEstadoSolicitud === 'APROBADA');
      control.setValue('observaciones', actividad?.observacion);
      setMostrarObservacionSoloLectura(true);
      setMostrarObservacionGrupo2(false);
      setLoading(false);
    }
    else if ((seccion && seccion === TABS_INDEX.SEGURIDADDOCUMENTAL || seccion === TABS_INDEX.INCONSISTENCIAS) &&
      trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Seguridad documental grupo 2') 
      && (item?.descripcionEstadoSolicitud === 'APROBADA' || 
          item?.descripcionEstadoSolicitud === 'EN VERIFICACION' ||
          item?.descripcionEstadoSolicitud === 'PENDIENTE' ||
          item?.descripcionEstadoSolicitud === 'BLOQUEADO' ||
          item?.descripcionEstadoSolicitud === 'INCONSISTENTE'))) {

      const observacionGrupo1 = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Seguridad documental grupo 1'));
      control.setValue('observacionesGrupo1', observacionGrupo1?.observacion);
      actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Seguridad documental grupo 2') && 
          (item?.descripcionEstadoSolicitud === 'APROBADA' || 
          item?.descripcionEstadoSolicitud === 'EN VERIFICACION' ||
          item?.descripcionEstadoSolicitud === 'PENDIENTE' ||
          item?.descripcionEstadoSolicitud === 'BLOQUEADO' ||
          item?.descripcionEstadoSolicitud === 'INCONSISTENTE'));
          control.setValue('observaciones', String(actividad?.observacion === null ? '' : actividad?.observacion));
          setMostrarObservacionSoloLectura(true);
          setMostrarObservacionGrupo2(true);
          setLoading(false);
    }
    else if (seccion && seccion === TABS_INDEX.INCONSISTENCIAS &&
      trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Seguridad documental grupo 1') && (item?.descripcionEstadoSolicitud === 'APROBADA'))) {

      actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Seguridad documental grupo 1') && (item?.descripcionEstadoSolicitud === 'APROBADA'));
      control.setValue('observaciones', actividad?.observacion);
      setMostrarObservacionSoloLectura(true);
      setMostrarObservacionGrupo2(true);
      setLoading(false);
    }
    else if (seccion && seccion === TABS_INDEX.INCONSISTENCIAS &&
      trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Seguridad documental grupo 1') && (item?.descripcionEstadoSolicitud === 'PENDIENTE' || item?.descripcionEstadoSolicitud === 'BLOQUEADO' || item?.descripcionEstadoSolicitud === 'EN VERIFICACION'))) {

      actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Seguridad documental grupo 1') && (item?.descripcionEstadoSolicitud === 'PENDIENTE' || item?.descripcionEstadoSolicitud === 'BLOQUEADO' || item?.descripcionEstadoSolicitud === 'EN VERIFICACION'));
      control.setValue('observaciones', String(actividad?.observacion === null ? '' : actividad?.observacion));
      setMostrarObservacionGrupo2(false);
      setLoading(false);
    }
    else if (seccion && seccion === TABS_INDEX.TRAMITEDEPAGO &&
      trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual') && (item?.descripcionEstadoSolicitud === 'APROBADA'))){

      actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Trámite de pago'));
      control.setValue('observaciones', String(actividad?.observacion === null ? '' : actividad?.observacion));
      if(trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Trámite de pago') && item?.descripcionEstadoSolicitud === 'APROBADA')){
        setMostrarObservacionSoloLectura(true);
      }
      if(!trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Trámite de pago') && item?.descripcionEstadoSolicitud === 'APROBADA')){
         setMostrarObservacionSoloLectura(false);
      }
      setMostrarObservacionGrupo2(false);
      setLoading(false);
    }
    else if ((seccion && seccion === TABS_INDEX.VERIFICACIONCUENTAINDIVIDUAL || seccion === TABS_INDEX.VERIFICACIONESDECUENTA) &&
            trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual')) &&
            !trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación novedades')) &&
            !trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación embargos'))){

        actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual'));
        control.setValue('observaciones', String(actividad?.observacion === null ? '' : actividad?.observacion));
        if(trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual') && item?.descripcionEstadoSolicitud === 'APROBADA')){
           setMostrarObservacionSoloLectura(true);
        }
        if(!trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual') && item?.descripcionEstadoSolicitud === 'APROBADA') &&
            trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual') && item?.descripcionEstadoSolicitud !== 'APROBADA')){
            setMostrarObservacionSoloLectura(false);
        }
        setMostrarObservacionGrupo2(false);
        setLoading(false);
    }
    else if ((seccion && seccion === TABS_INDEX.VERIFICACIONCUENTAINDIVIDUAL || seccion === TABS_INDEX.VERIFICACIONESDECUENTA) &&
      !trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual')) &&
       trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación novedades')) &&
      !trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación embargos'))){

        actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Verificación novedades'));
        control.setValue('observaciones', String(actividad?.observacion === null ? '' : actividad?.observacion));
        setMostrarObservacionGrupo2(false);
        setLoading(false);
    }
    else if ((seccion && seccion === TABS_INDEX.VERIFICACIONCUENTAINDIVIDUAL || seccion === TABS_INDEX.VERIFICACIONESDECUENTA) &&
     trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual')) &&
     trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación novedades')) &&
    !trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación embargos'))){

      const observacionNovedades = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Verificación novedades'));
      control.setValue('observacionesGrupo1', observacionNovedades?.observacion);
      actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual'));
      control.setValue('observaciones', String(actividad?.observacion === null ? '' : actividad?.observacion));
      setMostrarObservacionGrupo2(true);
      setLoading(false);
  }   
  // verificación embargos
  // else if ((seccion && seccion === TABS_INDEX.VERIFICACIONCUENTAINDIVIDUAL || seccion === TABS_INDEX.VERIFICACIONESDECUENTA) &&
  //     trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual')) &&
  //     trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación novedades')) &&
  //     trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación embargos'))){

  //     const observacionNovedades = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Verificación novedades'));
  //     control.setValue('observacionesGrupo1', observacionNovedades?.observacion);
  //     actividad = trazabilidad?.find((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual'));
  //     control.setValue('observaciones', String(actividad?.observacion === null ? '' : actividad?.observacion));
  //     setMostrarObservacionGrupo2(true);
  //     setMostrarObservacionVerificacion(false);
  //     setLoading(false);
  // }
  }

  const tituloObservacionGrupo1 = () => {
    let titulo = '';
    if(trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Seguridad documental grupo 2')) &&
       seccion === TABS_INDEX.INCONSISTENCIAS || seccion === TABS_INDEX.SEGURIDADDOCUMENTAL ){
        titulo = 'Observaciones Grupo 1';
    }else if(trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación')) &&
       seccion === TABS_INDEX.VERIFICACIONCUENTAINDIVIDUAL || seccion === TABS_INDEX.VERIFICACIONESDECUENTA){
        titulo = 'Observaciones Verificación de Novedades en los Datos';
    }
    return titulo;
  }

  const tituloObservacionGrupo2 = () => {
    let titulo = '';
    if(trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Seguridad documental grupo 2')) &&
      seccion === TABS_INDEX.INCONSISTENCIAS || seccion === TABS_INDEX.SEGURIDADDOCUMENTAL){
      titulo = 'Observaciones Grupo 2';
    }else if(trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación')) &&
     seccion === TABS_INDEX.VERIFICACIONCUENTAINDIVIDUAL || seccion === TABS_INDEX.VERIFICACIONESDECUENTA){
     titulo = 'Observaciones Verificación de Cuenta Individual';
    }
    return titulo;
  }

  const labelObservacionGrupo2 = () => {
    let label = '';
    if ((trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Seguridad documental grupo 2') && item?.descripcionEstadoSolicitud === 'APROBADA'))
      && seccion && seccion === TABS_INDEX.SEGURIDADDOCUMENTAL) {
      label = '';
    } 
    else if((trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual') && item?.descripcionEstadoSolicitud === 'APROBADA'))
      && seccion && seccion === TABS_INDEX.VERIFICACIONCUENTAINDIVIDUAL){
      label = '';
    }
    else {
      label = 'Si tiene observaciones adicionales ingreselas';
    }
    return label;
  }

  const isReadOnlyGrupo2 = () => {
    let soloLectura = false;
    if ((trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Seguridad documental grupo 2') && item?.descripcionEstadoSolicitud === 'APROBADA'))
      && seccion && seccion === TABS_INDEX.SEGURIDADDOCUMENTAL) {
         soloLectura = true;
    }
    if ((trazabilidad?.some((item: any) => String(item?.descripcionTarea).includes('Verificación cuenta individual') && item?.descripcionEstadoSolicitud === 'APROBADA'))
    && seccion && (seccion === TABS_INDEX.VERIFICACIONCUENTAINDIVIDUAL || TABS_INDEX.INCONSISTENCIAS)) {
       soloLectura = true;
    }
    return soloLectura;
  }

  if (loading) {
    return <CHLoadingProcess />;
  }

  return (
    <>
      {!mostrarObservacionGrupo2 && (
        <CHPaper title='Observaciones'>
          <Grid container>
            <Grid className={classes.column} item xs={12}>
              <Controller
                name='observaciones'
                control={control.control}
                rules={{
                  required: 'Este campo es requerido.',
                  maxLength: 1000
                }}
                render={({
                  field: { onChange, value },
                  fieldState: { error },
                }) => (
                  <CHTextField
                    error={!!error}
                    helperText={error ? error.message : null}
                    isReadOnly={mostrarObservacionSoloLectura}
                    InputLabelProps={{ shrink: true }}
                    label={!mostrarObservacionSoloLectura ? 'Si tiene observaciones adicionales ingreselas' : ''}
                    value={value}
                    required
                    multiline
                    minRows={2}
                    onChange={onChange}
                  />
                )}
              />
            </Grid>
          </Grid>
        </CHPaper>
      )}

      {mostrarObservacionGrupo2 && (
        <>
          <CHPaper title={tituloObservacionGrupo1()}>
            <Grid container>
              <Grid className={classes.column} item xs={12}>
                <Controller
                  name="observacionesGrupo1"
                  control={control.control}
                  rules={{
                    required: 'Este campo es requerido.',
                    maxLength: 1000,
                  }}
                  render={({ field: { onChange, value }, fieldState: { error } }) => (
                    <CHTextField
                      error={!!error}
                      helperText={error ? error.message : null}
                      InputLabelProps={{ shrink: true }}
                      isReadOnly
                      value={value}
                      required
                      multiline
                      minRows={2}
                      onChange={onChange}
                    />
                  )}
                />
              </Grid>
            </Grid>
          </CHPaper>
          <CHPaper title={tituloObservacionGrupo2()}>
            <Grid container>
              <Grid className={classes.column} item xs={12}>
                <Controller
                  name='observaciones'
                  control={control.control}
                  rules={{
                    required: 'Este campo es requerido.',
                    maxLength: 1000,
                  }}
                  render={({ field: { onChange, value }, fieldState: { error } }) => (
                    <CHTextField
                      error={!!error}
                      helperText={error ? error.message : null}
                      InputLabelProps={{ shrink: true }}
                      label={labelObservacionGrupo2()}
                      isReadOnly={isReadOnlyGrupo2()}
                      value={value}
                      required
                      multiline
                      minRows={2}
                      onChange={onChange}
                    />
                  )}
                />
              </Grid>
            </Grid>
          </CHPaper>

        </>
      )}
    </>
  )
}

export default ObservacionesSolicitud;