import React, { useEffect, useState } from 'react';
import { connect } from 'react-redux';
import { Button, createStyles, Grid, makeStyles } from '@material-ui/core';
import { toast } from 'react-toastify';
import { AppState } from '../../../store/rootReducer';
import CHPaperNew from '../../../components/ch-paper-new/CHPaperNew';
import { EducationalEntitiesState } from '../../../reducers/educationalEntities.reducer';
import { startGetAllEntidadBancaria, startGetAllValoresCatalogoPorNombre } from '../../../actions/catalog.action';
import CreateAccount from './createAccount';
import { CatalogState } from '../../../reducers/catalog.reducer';
import {
	startGetCuentas,
	startAddCuenta,
	startUpdateCuenta,
	startDeleteCuenta,
} from '../../../actions/educationalEntities.actions';
import { CuentaEntidadesEducativas } from '../../../types/educational.entities.type';
import UtilService from '../../../utils/util.service';
import ApiEntidadesEducativas from '../../../services/api-entidadesEducativas.service';

const useStyles = makeStyles(() =>
	createStyles({
		column: {
			padding: '50px',
			textAlign: 'left',
			color: '#42b7ef',
			borderColor: 'fec917',
		},

		processButton: {
			backgroundColor: '#42b7ef',
			color: '#fff',
			width: '12%',
			marginLeft: '69%',
		},

		processButton2: {
			backgroundColor: '#fec917',
			color: '#1c3f8b',
			width: '12%',
			marginLeft: '1%',
		},

		icon: {
			padding: '8px',
			textAlign: 'inherit',
			color: '#42b7ef',
			margin: '10px',
		},

		iconAmarillo: {
			padding: '8px',
			textAlign: 'inherit',
			color: '#1c3f8b',
			margin: '10px',
		},

		iconRed: {
			padding: '8px',
			textAlign: 'inherit',
			color: '#FF0000',
			margin: '10px',
		},

		marginInput: {
			margin: '2%',
			marginLeft: '5%',
		},

		button: {
			backgroundColor: '#1C3F8B',
			color: '#fff',
			width: '20%',
			marginRight: '1%',
		},
	}),
);

function Accounts({
	idEntidad,
	educationalEntitiesState,
	catalogState,
	obtenerCuentasEntidad,
}: {
	idEntidad: string;
	educationalEntitiesState: EducationalEntitiesState;
	catalogState: CatalogState;
	obtenerCuentasEntidad: (idEntidad: string) => void;
}): any {
	const classes = useStyles();
	const [isOpenCreate, setIsOpenCreate] = useState<boolean>(false);
	const [dataModal, setDataModal] = useState<any>({});
	const apiEntidadesEducativas = ApiEntidadesEducativas();

	const datos = () => {
		obtenerCuentasEntidad(idEntidad);
	}

	useEffect(() => {
		console.log(educationalEntitiesState)
		obtenerCuentasEntidad(idEntidad);

	}, []);

	const onClose = () => {
		setIsOpenCreate(false);
	};

	const openCreateOrUpdateModal = (data: any = null) => {
		setDataModal(data);
		setIsOpenCreate(true);
	};

	const DeleteFidecomiso = (data: any) => {
		apiEntidadesEducativas
			.DeleteFidecomiso(data)
			.then(async (response) => {
				if (response) {
					if (response.isSuccess) {
						obtenerCuentasEntidad(idEntidad);
						toast("Fideicomiso eliminado correctamente", { type: toast.TYPE.SUCCESS });
					}
				}
			}).catch(() => {
				toast("Error del sistema", { type: toast.TYPE.ERROR });
			});
	}

	return (
		<Grid container>
			<CHPaperNew>
				<table className="table">
					<thead>
						<tr>
							<th className="head">Tipo de Identificacion</th>
							<th className="head">N° Identificación</th>
							<th className="head">Razón Social</th>
							<th className="head">Fecha Creacion</th>
						</tr>
					</thead>
					<tbody>
						{educationalEntitiesState?.cuentas?.map((row: any, index: any) => (
							<tr key={`table-realStateRegistrations${index}`}>
								<td className="tab-space-02">
									{row?.tipoDocumento}
								</td>
								<td className="tab-space-02">
									{row?.nroIdentificacion}
								</td>
								<td className="tab-space-02">
									{row?.nombreRazonSocial}
								</td>
								<td className="tab-space-01">
									{UtilService.getFullDate(row.fecCreacion)}
								</td>
								<td data-label="acciones" className="tab-space-01">
									<span aria-label="Detalle" onClick={() => openCreateOrUpdateModal(row)}><span className="ico fch-Hoja-Vida-0-1 icoMid-3" /></span>
									<span aria-label="Eliminar" onClick={() => DeleteFidecomiso(row.enE_FIDEICOMISO_ID!)}><span className={`ico fch-Eliminar-0-1 icoMid-3 ${classes.iconRed}`} /></span>
								</td>
							</tr>
						))}
					</tbody>
				</table>
				<div className="buttons">
					<Button
						className={classes.button}
						variant="outlined"
						onClick={() => openCreateOrUpdateModal()}
					>
						AGREGAR FIDEICOMISO
					</Button>
				</div>
			</CHPaperNew>
			<CreateAccount
				isOpen={isOpenCreate}
				dataModel={dataModal}
				catalogState={catalogState}
				onClose={onClose}
				Fidecomiso={datos}
				idEntidad={idEntidad}
			/>
		</Grid>
	);
}

const mapStateToProps = (state: AppState) => ({
	catalogState: state.catalog,
	educationalEntitiesState: state.educationalEntities,
});

const mapDispatchToProps = (dispatch: any) => ({
	obtenerCuentasEntidad: (idEntidad: string) =>
		dispatch(startGetCuentas(idEntidad)),
	obtenerEntidadesBancarias: () =>
		dispatch(startGetAllEntidadBancaria()),
	obtenerTipoCuenta: (nombreCatalogo: string) =>
		dispatch(startGetAllValoresCatalogoPorNombre(nombreCatalogo)),
	crearCuenta: (cuentaEntidad: CuentaEntidadesEducativas) =>
		dispatch(startAddCuenta(cuentaEntidad)),
	actualizarCuenta: (cuentaEntidad: CuentaEntidadesEducativas) =>
		dispatch(startUpdateCuenta(cuentaEntidad)),
	borrarCuenta: (idCuentaBancaria: string) =>
		dispatch(startDeleteCuenta(idCuentaBancaria))
});

export default connect(mapStateToProps, mapDispatchToProps)(Accounts);