import React, { useEffect, useState } from 'react';
import {
    Dialog,
    DialogContent, Typography, Button, makeStyles, createStyles, DialogActions,
    Grid, CardContent, Card, MenuItem
} from '@material-ui/core';
import { connect } from 'react-redux';
import { Controller, useForm } from 'react-hook-form';
import swal from 'sweetalert';
import { toast } from 'react-toastify';
import CHTextField from '../../../../components/ch-text-field/CHTextField';
import TituloIcono from '../titulo-icono/tituloIcono.component';
import CHSelect from '../../../../components/ch-select/CHSelect';
import { CAUSALBLOQUEOCUENTA } from '../../../../types/catalog.type';
import { startActualizaBloqueoCuentas } from '../../../../actions/catalog.action';
import CatalogApi from '../../../../services/api-catalog.service';
import CHCheckboxV2 from '../../../../components/ch-checkbox/CHCheckboxV2';



const useStyles = makeStyles(() =>
    createStyles({
        dialogPaper: {
            width: '60%',
            height: '60%'
        },
        dialogTitles: {
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between'
        },
        buttonClose: {
            position: 'absolute',
            right: '8',
            top: '8'
        },
        root: {
            flexGrow: 1,
        },
        gridPadding: {
            padding: '1rem'
        },
        cardContent: {
            margin: '0',
            padding: '0rem'
        },
        dialogRoot: {
            padding: '.5rem'
        },
        marginTops: {
            marginTop: '1rem'
        },
        maxheight: {
            height: '100%'
        },
        titulo: {
            marginLeft: '30%'
        }
    })
);


const api = CatalogApi();

export const ModalBloqueoDeCuenta = (props: Props) => {

    const { startActualizaBloqueoCuentas, open, handleClose, tipoCuenta, cuentaIdOrIdConcepto, tipoBloqueos, valueCuenta, responseAdminCuenta, idCuenta } = props;
    const { control, watch, handleSubmit } = useForm({
        defaultValues: {
            causalBloqueoId: 0,
            tipoCuentaConcepto: '',
            conceptoId: 0,
            porcentaje: '',
            valor: '',
            observaciones: '',
            typerequest: '',
            bloquearTodosConceptos: false
        },
    });

    const[causalesBloqueo, setCausalesBloqueo] = useState<any[]>([]);

    const fetchCausales = async() => {
        await api
            .getCausalesBloqueoCuenta()
            .then(async (response: any) => {
                if (response) {
                    if (response.isSuccess) {
                        setCausalesBloqueo(response.data)
                    }
                }
            })
            .catch(() => {
                toast('Error del sistema', { type: toast.TYPE.ERROR });
            });
    };

    useEffect(() => {
        fetchCausales()
    
    }, [])

    const onSubmit = (data: any) => {

        swal({
            text: "¿Está seguro de bloquear la cuenta?",
            icon: "info",
            buttons: ["No", "Sí"]
        }).then(async respuesta => {
            if (respuesta) {
                startActualizaBloqueoCuentas({
                    CausalBloqueoId: data.causalBloqueoId,
                    cuentaId: cuentaIdOrIdConcepto,
                    conceptoId: cuentaIdOrIdConcepto,
                    tipoBloqueo: tipoCuenta === 'CUENTA' ? 'CUENTA' : 'CONCEPTO',
                    monto: true,
                    valor: data.valor === '' ? 0 :  parseInt(data.valor.replace('$','').replace(',',''),20),
                    estado: false
                });
                handleClose();
            }
        })

    }

    const classes = useStyles();
    const [bloqueoTodosConceptos, setBloqueoTodosConceptos] = useState(false);

 

    return (
        <>
            <div> 
                
                <Dialog classes={{ paper: classes.dialogPaper }}
                    open={open}
                    onClose={handleClose}
                    maxWidth="lg"

                >
                    <Grid className={classes.titulo}>
                    <div >
                        <Typography
                            variant="h5"
                            component="h5"
                            className={classes.dialogTitles}
                        >
                            Bloquear Cuentas ó Conceptos
                        </Typography>
                    </div>
                    <div className={classes.marginTops}>
                        {' '}
                    </div>
                    </Grid>
                    <Grid className='subcontainerModal'>
                    <div className={classes.maxheight} >

                        <Card className={classes.maxheight}>

                            <Grid className="container-ico-t marginTopContainerPopup">
                                <span className="ico fch-Puntual-0 blue-2 icoLit" />
                                <span className="ico fch-Arrow-0-0 gray-2 icoLit-2 ico-b" />
                                <span className="tittle-tab blue-2 tittle-we">Bloquear Cuenta Número :  {cuentaIdOrIdConcepto}</span>
                            </Grid>
                            
                            <CardContent className={classes.maxheight}>

                                <DialogContent className={classes.maxheight}>


                                    <Grid container justifyContent="space-around">
                                        <Grid item xs={3}>
                                            <TituloIcono
                                                title1="Tipo"
                                                subtitle="de causal"
                                                icono="event_available"
                                            />
                                        </Grid>
                                        <Grid item xs={6} >
                                            <Controller
                                                name="causalBloqueoId"
                                                control={control}
                                                rules={{
                                                    required: 'Este campo es requerido.',
                                                }}
                                                render={({
                                                    field: { onChange, value },
                                                    fieldState: { error },
                                                }) => (
                                                    <CHSelect
                                                        error={!!error}
                                                        label=""
                                                        value={value}
                                                        helperText={error ? error.message : null}
                                                        onChange={onChange}
                                                    >
                                                        {causalesBloqueo?.map(
                                                            (option: any) => (
                                                                <MenuItem
                                                                    key={option.idCausal}
                                                                    value={option.idCausal}
                                                                >
                                                                    {option.descripcionCausal}
                                                                </MenuItem>
                                                            )
                                                        )}

                                                    </CHSelect>
                                                )}
                                            />
                                        </Grid>
                                    </Grid>
                                    <br />
                                    <br />
                                    <Grid container justifyContent="space-around">
                                        <Grid item xs={3}>
                                            <TituloIcono
                                                title1="Tipo de "
                                                subtitle="Cuenta"
                                                icono="event_available"
                                            />
                                        </Grid>
                                        <Grid item xs={6} >
                                            <Controller
                                                name="tipoCuentaConcepto"
                                                control={control}
                                                render={({
                                                    field: { onChange },
                                                    fieldState: { error },
                                                }) => (
                                                    <CHTextField
                                                        isReadOnly={false}
                                                        error={!!error}
                                                        helperText={error ? error.message : null}
                                                        value={valueCuenta}
                                                        onChange={onChange}
                                                    />
                                                )}
                                            />
                                        </Grid>
                                    </Grid>
                                    <br />
                                    <br />

                                    <Grid container justifyContent="space-around">
                                        <Grid item xs={3}>
                                            <TituloIcono
                                                title1="Concepto"
                                                subtitle=""
                                                icono="event_available"
                                            />
                                        </Grid>
                                        <Grid item xs={6} >
                                            <Controller
                                                name="conceptoId"
                                                control={control}
                                                render={({
                                                    field: { onChange, value },
                                                }) => (
                                                    <CHSelect
                                                        label=""
                                                        value={watch('bloquearTodosConceptos') ? 0 : value}
                                                        onChange={onChange}
                                                        disabled={watch('bloquearTodosConceptos')}
                                                    >
                                                        {responseAdminCuenta?.cuentas?.find((x: any) => x.cuentaId === idCuenta)?.conceptos.map(
                                                            (option: any) => (
                                                                <MenuItem
                                                                    key={option.id}
                                                                    value={option.id}
                                                                >
                                                                    {option.descripcionConcepto}
                                                                </MenuItem>
                                                            )
                                                        )}

                                                    </CHSelect>
                                                )}
                                            />
                                            <Controller
                                                name="bloquearTodosConceptos"
                                                control={control}
                                                render={({
                                                    field: { onChange, value },
                                                }) => (
                                                    <CHCheckboxV2
                                                        label='Bloquear todos los conceptos'
                                                        checked={value}
                                                        onChange={onChange}
                                                    />
                                                )}
                                            />
                                        </Grid>
                                    </Grid>
                                    <br />
                                    <br />
                                    <Grid container justifyContent="space-around">
                                        <Grid item xs={3}>
                                            <TituloIcono
                                                title1="Valor o"
                                                subtitle="Porcentaje"
                                                icono="event_available"
                                            />
                                        </Grid>
                                        <Grid item xs={6} >
                                            <Controller
                                                name="porcentaje"
                                                control={control}
                                                render={({
                                                    field: { onChange, value },
                                                    fieldState: { error },
                                                }) => (
                                                    <CHTextField
                                                        currencyMask
                                                        error={!!error}
                                                        helperText={error ? error.message : null}
                                                        value={value}
                                                        onChange={onChange}
                                                    />
                                                )}
                                            />
                                        </Grid>
                                    </Grid>
                                    <br />
                                    <br />
                                    <Grid container justifyContent="space-around">
                                        <Grid item xs={3}>
                                            <TituloIcono
                                                title1="Monto o"
                                                subtitle="Valor"
                                                icono="event_available"
                                            />
                                        </Grid>
                                        <Grid item xs={6} >
                                            <Controller
                                                name="valor"
                                                control={control}
                                                render={({
                                                    field: { onChange, value },
                                                    fieldState: { error },
                                                }) => (
                                                    <CHTextField
                                                        currencyMask
                                                        error={!!error}
                                                        helperText={error ? error.message : null}
                                                        value={value}
                                                        onChange={onChange}
                                                    />
                                                )}
                                            />
                                        </Grid>
                                    </Grid>
                                    
                                    <br />
                                    <br />
                                    <Grid container justifyContent="space-around">
                                        <Grid item xs={3}>
                                            <TituloIcono
                                                title1="Observaciones"
                                                subtitle=""
                                                icono="event_available"
                                            />
                                        </Grid>
                                        <Grid item xs={6} >
                                            <Controller
                                                name="observaciones"
                                                control={control}
                                                render={({
                                                    field: { onChange, value },
                                                    fieldState: { error },
                                                }) => (
                                                    <CHTextField
                                                        maxRows={5}
                                                        multiline
                                                        error={!!error}
                                                        helperText={error ? error.message : null}
                                                        value={value}
                                                        onChange={onChange}
                                                    />
                                                )}
                                            />
                                        </Grid>
                                    </Grid>

                                    
                                </DialogContent>
                            </CardContent>
                        </Card>
                    </div>
                    </Grid>
                    <DialogActions className='maginButtonAddClose'>
                        <Button onClick={handleClose} variant="contained">
                            Cancelar
                        </Button>
                        <Button onClick={handleSubmit(onSubmit)} variant="contained">
                            Guardar
                        </Button>
                    </DialogActions>
                </Dialog>
            </div>
        </>
    );
}


interface LinkMapDispatchToProps {
    valueCuenta: string;
    open: boolean;
    handleClose: () => void;
    tipoCuenta: string;
    cuentaIdOrIdConcepto: number;
    tipoBloqueos: CAUSALBLOQUEOCUENTA[];
    startActualizaBloqueoCuentas: (data: any) => void;
    responseAdminCuenta: any;
    idCuenta: any; 
}

const mapDispatchToProps = {
    startActualizaBloqueoCuentas
};



type Props = LinkMapDispatchToProps;

export default connect(null, mapDispatchToProps)(ModalBloqueoDeCuenta)