import React from 'react';
import { Controller, useForm, useFormContext, UseFormReturn } from 'react-hook-form';
import { makeStyles, createStyles, Grid, Button } from '@material-ui/core';
import CHPaper from '../../../../components/ch-paper/CHPaper';
import CHTextField from '../../../../components/ch-text-field/CHTextField';

const useStyles = makeStyles(() =>
  createStyles({
    column: {
      padding: '10px',
      textAlign: 'center',
    }
  }),
);

const ObservacionesInicioSolicitud = ({
  control,
  formularioAcreditacion
}:{
  control: UseFormReturn<any>;
  formularioAcreditacion?: UseFormReturn<any>;
}) => {
  const classes = useStyles();

  return (
    <CHPaper title='Observaciones'>
      <Grid container>
        <Grid className={classes.column} item xs={12}>
          <Controller
            name='observaciones'
            control={formularioAcreditacion?.control || control?.control}
            // control={control?.control}
            rules={{
              required: 'Este campo es requerido.',
              maxLength: 1000
            }}
            render={({
              field: { onChange, value },
              fieldState: { error },
            }) => (
              <CHTextField
                error={!!error}
                helperText={error ? error.message : null}
                InputLabelProps={{ shrink: true }}
                label='Si tiene observaciones adicionales ingreselas'
                value={value}
                required
                multiline
                minRows={2}
                onChange={onChange}
              />
            )}
          />
        </Grid>
      </Grid>
    </CHPaper>
  )
}

export default ObservacionesInicioSolicitud;
