import React, { useEffect, useState } from 'react';
import {
    Button,
    createStyles,
    Grid,
    makeStyles,
    MenuItem,
} from '@material-ui/core';
import { Controller, useForm } from 'react-hook-form';
import { toast } from 'react-toastify';
import CHDatePicker from '../../components/ch-datepicker/CHDatepicker';
import CHPageTitle from '../../components/ch-page-title/CHPageTitle';
import CHPaper from '../../components/ch-paper/CHPaper';
import CHPrivateContainer from '../../components/ch-private-container/CHPrivateContainer';
import CHTextField from '../../components/ch-text-field/CHTextField';
import {
    CATALOG,
    ConsultaPreaprobadoForm,
} from './constans/preaprobadoform.model.type';
import { LoadingComponent } from '../../components/loading/loading.component';
import {
    ConsultaPreaprobado,
    PreaprobadoDto,
} from '../../types/preaprobados.model.type';
import CHSelect from '../../components/ch-select/CHSelect';
import NotificationService from '../../services/notification.service';
import InformacionPreaprobado from './InformacionPreaprobado';
import ApiCatalog from '../../services/api-catalog.service';
import ApiCredit from '../../services/api-credit.service';
import { VALORCATALOGO } from '../../types/catalog.type';
import UtilService from '../../utils/util.service';
import AuthService from '../../services/auth.service';
import AuditoriaApi from '../../services/api-auditorias.servise'
import { Auditoria } from '../../types/Auditoria.model.type';

const useStyles = makeStyles(() =>
    createStyles({
        column: {
            padding: '10px',
            textAlign: 'center',
        },
        button: {
            width: '400px',
            marginLeft: '.5rem',
        },
        column2: {
            padding: '10px',
            textAlign: 'left',
        },
        processButton: {
            backgroundColor: '#1C3F8B',
            color: '#fff',
            margin: '8px 0',
        },
    }),
);

function PreaprobadoTable({
    data,
    isDataLoaded,
    onClickItem,
}: {
    data: PreaprobadoDto[];
    isDataLoaded: boolean;
    onClickItem: (data: PreaprobadoDto) => void;
}) {
    const classes = useStyles();
    const [loading, setLoading] = useState(false);

    if (!isDataLoaded) {
        return null;
    }

    if (data.length === 0) {
        return <div>No se encontraron resultados</div>;
    }

    return (
        <>
            <LoadingComponent loading={loading} />
            <table
                className="client-table"
                style={{
                    margin: '20px',
                    width: '95%',
                }}
            >
                <thead>
                    <tr>
                        <th> </th>
                        <th style={{ textAlign: 'center' }}>Tipo Crédito</th>
                        <th style={{ textAlign: 'center' }}>
                            Fecha Preaprobado
                        </th>
                        <th style={{ textAlign: 'center' }}>
                            Número Documento
                        </th>
                        <th style={{ textAlign: 'center' }}>
                            Apellidos y Nombres
                        </th>
                        <th style={{ textAlign: 'center' }}>
                            Valor Solicitado
                        </th>
                        <th style={{ textAlign: 'center' }}>
                            Número Preaprobado
                        </th>
                        <th style={{ textAlign: 'center' }}>Estado</th>
                    </tr>
                </thead>
                <tbody>
                    {data?.map((row, index) => (
                        <tr key={`tr${index}`}>
                            <td>
                                <Button
                                    className={classes.processButton}
                                    onClick={() => {
                                        setLoading(true);
                                        onClickItem(row);
                                    }}
                                >
                                    Detalle
                                </Button>
                            </td>
                            <td>{row.descripcion}</td>
                            <td>{UtilService.getDate(row.fechaAprobacion)}</td>
                            <td>{row.numeroDcocumento}</td>
                            <td>{`${row.primerNombre}${row.segundoNombre}${row.primerApellido}${row.segundoApellido}`}</td>
                            <td>{row.valorPrestamo}</td>
                            <td>{row.numeroPreaprobado}</td>
                            <td>
                                {row.estado === 'C' ? 'COMPLETO' : 'INCOMPLETO'}
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
        </>
    );
}

const PreaprobacionesInicio = () => {
    const classes = useStyles();
    const apiCatalog = ApiCatalog();
    const apiCredit = ApiCredit();
    const [selectedData, setSelectedData] = useState<PreaprobadoDto | null>(
        null,
    );
    const [preaprobados, setPreaprobados] = useState<PreaprobadoDto[]>([]);
    const [isDataLoaded, setIsDataLoaded] = useState(false);
    const [estadoPreaprobado, setEstadoPreaprobado] = useState<VALORCATALOGO[]>(
        [],
    );
    const [loading, setLoading] = useState(false);

    const formularioConsulta = useForm({
        defaultValues: ConsultaPreaprobadoForm,
    });

    useEffect(() => {
        consultarCatalogoListaParentesco(CATALOG.ESTADO);
    }, []);

    const onItemIsSelected = (data: PreaprobadoDto | null) => {
        setSelectedData(data);
    };

    const onItemGoBack = () => {
        setSelectedData(null);
        setPreaprobados([]);
        setIsDataLoaded(false);
        formularioConsulta.reset();
    };

    const consultarCatalogoListaParentesco = async (idCatalogo: number) => {
        await apiCatalog
            .getAllCatalogoPorId(idCatalogo)
            .then(async (response: any) => {
                if (response) {
                    if (response.isSuccess) {
                        setEstadoPreaprobado(response?.data);
                    }
                }
            })
            .catch(e => {
                toast('Error del sistema', { type: toast.TYPE.ERROR });
            });
    };

    const [publicIpAddress, setPublicIpAddress] = useState<string | null>(null);
    const [localIpAddress, setLocalIpAddress] = useState<string | null>(null);
    const catalogApi = ApiCatalog();

    const isValidIPv4 = (ip: string) => {
        const ipv4Regex = /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
        return ipv4Regex.test(ip);
    };

    const isValidIPv6 = (ip: string) => {
        const ipv6Regex = /([a-f0-9:]+:+)+[a-f0-9]+/i;
        return ipv6Regex.test(ip);
    };

    const enviarIp = async (ip: any) => {
        const convertIp = ip.split('.')[0]

        const hexadecimal = convertIp
        await catalogApi
            .getObtenerIpLocal(hexadecimal)
            .then(async (response: any) => {

                if (response) {
                    if (response.isSuccess) {
                        setPublicIpAddress(response.data);
                    }
                }
            })
            .catch(e => {
                toast('Error del sistema', { type: toast.TYPE.ERROR });
            });

    }

    useEffect(() => {
        const fetchLocalIPAddress = () => {
            const peerConnection = new RTCPeerConnection({ iceServers: [] });
            peerConnection.createDataChannel('');
            peerConnection.createOffer()
                .then((offer) => peerConnection.setLocalDescription(offer))
                .catch((error) => console.error('Error creating offer:', error));

            peerConnection.onicecandidate = (event) => {
                if (event.candidate) {
                    const ip: any = event.candidate.address;
                    if (isValidIPv4(ip) || isValidIPv6(ip)) {
                        setLocalIpAddress(ip);
                        enviarIp(ip);
                    } else {
                        setLocalIpAddress(ip);
                        enviarIp(ip);
                    }
                }
            };

            return () => {
                peerConnection.close();
            };
        };
        fetchLocalIPAddress();

    }, []);


    const handleSearchButton = async (data: ConsultaPreaprobado) => {
        if (data.fechaSimulacion !== null && data.fechaSimulacionFin) {
            if (data.fechaSimulacion > data.fechaSimulacionFin) {
                await NotificationService.genericAlert(
                    'Warning',
                    'La fecha inicial no puede ser mayor a la fecha final',
                    'warning',
                );
                return;
            }
        }
        const request: ConsultaPreaprobado = {
            numeroDocumento:
                data.numeroDocumento === '' ? null : data.numeroDocumento,
            fechaSimulacion: data.fechaSimulacion,
            fechaSimulacionFin: data.fechaSimulacionFin,
            estado: String(data.estado) === "" ? null : data.estado,
        };

        const auditoriaApi = AuditoriaApi();
        const user = AuthService.getUserInfo();
        const nav = window.navigator as any;
        const usrAg = nav.userAgentData.brands.find(
            (x: { brand: string }) => x.brand === 'Google Chrome' || x.brand === 'Microsoft Edge'
        )?.brand;

        try {
            const requestAuditoria = {
                navegador: usrAg,
                sistemaOperativo: nav.userAgentData.platform,
                nombreUsuario: user.USR_USERNAME,
                usurioId: user.USR_ID,
                ip: publicIpAddress,
                modulo: 'Consulta Preaprobados',
                hostname: document.location.host,
                tipoAccion: 'CONSULTAS',
                idTipoAccion: 3,
                descripcion: `Consulta de preaprobados con los siguientes filtros:
                    - Número de identificación: ${request.numeroDocumento || 'No especificada'}
                    - Fecha desde: ${request.fechaSimulacion || 'No especificado'}
                    - Fecha hasta: ${request.fechaSimulacionFin || 'No especificado'}
                    - Estado: ${request.estado || 'No especificado'}`

            } as Auditoria;

            auditoriaApi.InsertAuditoria(requestAuditoria);

            consultarPreaprobaciones(request);
            setIsDataLoaded(true);
        } catch (error: any) {

            const descripcionError = `Error al consultar preaprobados:
            - Número de identificación: ${request.numeroDocumento || 'No especificada'}
            - Fecha desde: ${request.fechaSimulacion || 'No especificado'}
            - Fecha hasta: ${request.fechaSimulacionFin || 'No especificado'}
            - Estado: ${request.estado || 'No especificado'}`;

            const requestAuditoriaError: Auditoria = {
                navegador: usrAg,
                sistemaOperativo: nav.userAgentData?.platform || 'No disponible',
                nombreUsuario: user?.USR_USERNAME || 'Desconocido',
                usurioId: user?.USR_ID || 0,
                ip: publicIpAddress || 'IP no disponible',
                modulo: 'Pago de Embargos',
                hostname: document.location.host,
                tipoAccion: 'ERRORES Y EXCEPCIONES',
                idTipoAccion: 8,
                descripcion: descripcionError,
            };

            await auditoriaApi.InsertAuditoria(requestAuditoriaError);

            NotificationService.genericAlertError("ERROR", "Error al obtener datos de la API.");

        }

    };

    const consultarPreaprobaciones = async (request: ConsultaPreaprobado) => {
        setLoading(true);
        await apiCredit
            .postObtenerPreaprobaciones(request)
            .then(async (response: any) => {
                if (response) {
                    if (response.isSuccess && response.data !== null) {
                        setPreaprobados(response.data);
                        setLoading(false);
                    } else {
                        setLoading(false);
                    }
                }
            })
            .catch(e => {
                toast('Error del sistema', { type: toast.TYPE.ERROR });
                setLoading(false);
            });
    };

    if (selectedData !== null) {
        return (
            <InformacionPreaprobado
                preapropado={selectedData}
                onItemGoBack={onItemGoBack}
            />
        );
    }

    return (
        <CHPrivateContainer>
            <CHPageTitle
                topText="Gestión Preaprobados"
                subText=""
                title1="Consulta"
                title2="Preaprobados"
            />

            <CHPaper title="Información consulta">
                <Grid container>
                    <Grid className={classes.column} item xs={12} md={3}>
                        <Controller
                            name="numeroDocumento"
                            control={formularioConsulta.control}
                            rules={{
                                pattern: /^[ A-zÀ-ú0-9 ]+$/g,
                            }}
                            render={({
                                field: { onChange, value },
                                fieldState: { error },
                            }) => (
                                <CHTextField
                                    error={!!error}
                                    helperText={error ? error.message : null}
                                    isReadOnly={false}
                                    InputLabelProps={{ shrink: true }}
                                    label="Número de Identificación"
                                    value={value}
                                    onChange={e => {
                                        if (e.target.value.length <= 20) {
                                            onChange(
                                                e.target.value.replace(
                                                    /[ñÑáéíóúÁÉÍÓÚ\W%-+*&#@=`~]/g,
                                                    '',
                                                ),
                                            );
                                        }
                                    }}
                                />
                            )}
                        />
                    </Grid>
                    <Grid className={classes.column} item xs={12} md={3}>
                        <Controller
                            name="fechaSimulacion"
                            control={formularioConsulta.control}
                            render={({
                                field: { onChange, value },
                                fieldState: { error },
                            }) => (
                                <CHDatePicker
                                    label="Fecha Desde"
                                    onChange={onChange}
                                    value={value}
                                    maxDate={new Date()}
                                    maxDateMessage="La fecha de alta no debe ser mayor a la actual"
                                    invalidDateMessage="Fecha inválida"
                                />
                            )}
                        />
                    </Grid>
                    <Grid className={classes.column} item xs={12} md={3}>
                        <Controller
                            name="fechaSimulacionFin"
                            control={formularioConsulta.control}
                            render={({
                                field: { onChange, value },
                                fieldState: { error },
                            }) => (
                                <CHDatePicker
                                    label="Fecha Hasta"
                                    onChange={onChange}
                                    value={value}
                                    maxDate={new Date()}
                                    maxDateMessage="La fecha de alta no debe ser mayor a la actual"
                                    invalidDateMessage="Fecha inválida"
                                />
                            )}
                        />
                    </Grid>
                    <Grid className={classes.column} item xs={12} md={3}>
                        <Controller
                            name="estado"
                            control={formularioConsulta.control}
                            render={({
                                field: { onChange, value },
                                fieldState: { error },
                            }) => (
                                <CHSelect
                                    label="Estado"
                                    value={value}
                                    onChange={onChange}
                                >
                                    <MenuItem key={0} value={0}>
                                        SELECCIONE...
                                    </MenuItem>
                                    {estadoPreaprobado?.map(
                                        (option: VALORCATALOGO) => (
                                            <MenuItem
                                                key={option.id}
                                                value={option.codigo}
                                            >
                                                {option.descripcion}
                                            </MenuItem>
                                        ),
                                    )}
                                </CHSelect>
                            )}
                        />
                    </Grid>
                </Grid>
            </CHPaper>
            <div className="buttons">
                <Button
                    className={classes.button}
                    variant="outlined"
                    onClick={formularioConsulta.handleSubmit(
                        handleSearchButton,
                    )}
                >
                    CONSULTAR
                </Button>
            </div>
            <LoadingComponent loading={loading} />
            <PreaprobadoTable
                data={preaprobados}
                onClickItem={onItemIsSelected}
                isDataLoaded={isDataLoaded}
            />
        </CHPrivateContainer>
    );
};

export default PreaprobacionesInicio;
