import React, { useEffect, useState } from 'react';
import { connect } from 'react-redux';
import { Grid, makeStyles, createStyles,Typography, } from '@material-ui/core';
import CHPaper from '../../../components/ch-paper/CHPaper';
import { CatalogState } from '../../../reducers/catalog.reducer';
import { ClienteDto } from '../../../types/client.model.type';
import UtilService from '../../../utils/util.service';


const useStyles = makeStyles(() =>
    createStyles({
        column: {
            padding: '10px',
            textAlign: 'center'
        }, 
        titleform: {
            width: '100%',
            textAlign: 'center',
            color: '#1C3F8B',
            padding: 1,
            fontWeight: 'bold',
            fontSize: '1rem',
        }, 
        titleCampo: {
            fontSize: '10px',
           
        },       
    }),
);

function Bloqueos({
    catalogState,
    clientModel,
}: {
    catalogState: CatalogState;
    clientModel: ClienteDto;
}){    
    
    const [bloqueos, setBloqueos] = useState<boolean>(false);
    const classes = useStyles(); 
    useEffect(() => {
        const validateBloqueos = () => {
            if(clientModel?.cuentas?.length !== 0) {
                clientModel?.cuentas?.forEach((element, index) => {
                    if(element.conceptosSaldosBloqueos?.length !== 0){
                        setBloqueos(true)
                    }
                })
            }
        }

        validateBloqueos()
    });
    
        return(
            <CHPaper title="Bloqueos">
                
                    <Typography className={classes.titleform} variant="h5" component="h6">
                        Bloqueos
                    </Typography>
                    {
                        bloqueos ? (
                            <table className="table">
                                <thead>
                                    <tr>
                                        <th>Radicado</th>
                                        <th>Solicitud</th>
                                        <th>Estado solicitud</th>
                                        <th>Estado bloqueo</th>
                                        <th>Demandante</th>
                                        <th>Cuenta</th>
                                        <th>Razón</th>
                                        <th>Monto/Porcentaje</th>
                                    </tr>
                                </thead>
        
                                <tbody>
                                    {clientModel?.cuentas?.map((element, index) => (
                                        element.conceptosSaldosBloqueos?.map((elementBloqueos: any, index1: number) => (
                                            elementBloqueos.valorAcumulado>0&&elementBloqueos.idCuenta>0?
    
                                            
                                        <tr key={`table-schedule${index1}`}>
                                            <td className='dateReport3'>{element.numeroCuenta}</td>
                                            <td className='dateReport3'>{element.numeroCuenta}</td>
                                            <td className='dateReport3'>PROCESADA</td>
                                            <td className='dateReport3'>{elementBloqueos.estadoBloqueo}</td>
                                            <td className='dateReport3'>{elementBloqueos.concepto}</td>
                                            <td className='dateReport3'>{element.numeroCuenta}</td>
                                            <td className='dateReport3'> </td>
                                            <td className='dateReport3'>{UtilService.formatCurrency(elementBloqueos.valorAcumulado)}</td>
                                        </tr>:null
                                       
                                        ))
                                    ))}
                                </tbody>
                            </table>
                            ) : 'El afiliado no cuenta con bloqueos'
                    }
            </CHPaper>   )
    }
   

export default connect()(Bloqueos);